INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '中央線や車両通行帯のない一般道路（いわゆる生活道路）では、最高速度の標識がなければ、自動車の法定最高速度は時速60キロメートルである。', '["○（正しい）","×（誤り）"]', 1, 2, '2026年9月施行の改正道路交通法により、中央線や車両通行帯のない生活道路の法定速度は時速30キロメートルに引き下げられました。中央線がある道路は原則60km/hです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '中央線（センターライン）が引かれている片側1車線の一般道路で、最高速度の標識がない場合、普通乗用車の法定最高速度は時速60キロメートルである。', '["○（正しい）","×（誤り）"]', 0, 2, '中央線や車両通行帯がある一般道路の法定最高速度は、標識がなければ時速60kmです。生活道路（30km/h）との違いに注意しましょう。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '普通自動車の仮免許を取得できる年齢は、2026年4月の改正により満17歳6か月以上となったが、実際に運転免許証が交付されるのは18歳に達してからである。', '["○（正しい）","×（誤り）"]', 0, 2, '2026年4月1日施行の改正により、普通免許・準中型免許の仮免許および本試験の受験資格が17歳6か月以上に引き下げられました。免許証の交付は18歳からとなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '自動車で自転車の側方を通過・追い越しするときは、自転車との間に十分な側方間隔を保つか、安全な速度で進行しなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '改正道路交通法で自転車の追い越しルールが明確化され、十分な側方間隔を保てない場合は安全な速度（徐行等）で進行する義務があります。', 'hazard_bicycle_overtake');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '2026年4月から導入された自転車の交通違反に対する反則通告制度（青切符）は、14歳以上の自転車利用者が対象となる。', '["○（正しい）","×（誤り）"]', 1, 2, '自転車の青切符制度の対象は「16歳以上」です。16歳未満の違反は指導・警告が中心となります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', 'マイナンバーカードと運転免許証を一体化した「マイナ免許証」を選択した場合でも、従来の運転免許証と両方を持つことは認められていない。', '["○（正しい）","×（誤り）"]', 1, 2, '2025年3月開始のマイナ免許証制度では、①従来の免許証のみ ②マイナ免許証のみ ③両方持ち の3通りから選択できます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '特定小型原動機付自転車（電動キックボード等の一定基準を満たすもの）は、16歳以上であれば運転免許がなくても運転できる。', '["○（正しい）","×（誤り）"]', 0, 1, '特定小型原動機付自転車は16歳以上であれば免許不要で運転できます（16歳未満の運転は禁止）。最高速度は20km/hです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '特定小型原動機付自転車で「特例特定小型原動機付自転車」として歩道を通行するときは、最高速度表示灯を点滅させ、時速6キロメートル以下で走行しなければならない。', '["○（正しい）","×（誤り）"]', 0, 2, '自転車歩道通行可の標識がある歩道等を通行できる「特例特定小型原動機付自転車」は、6km/h以下に制御し最高速度表示灯を点滅させる必要があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', 'この標識がある場所では、停止線がある場合でも、左右の見通しが良ければ徐行して通過することができる。', '["○（正しい）","×（誤り）"]', 1, 1, '「一時停止（止まれ）」の標識がある場所では、見通しの良し悪しにかかわらず、停止線（ない場合は交差点直前）で必ず一時停止しなければなりません。', 'sign_stop');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', 'この標識は「徐行」を表しており、車がすぐに停止できるような速度で進行しなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '「徐行」の標識です。徐行とは、車両等が直ちに停止することができるような速度（おおむね10km/h以下）で進行することをいいます。', 'sign_slow');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', 'この標識がある道路には、自転車や歩行者を含め、すべての車両が進入してはならない。', '["○（正しい）","×（誤り）"]', 1, 2, '「車両進入禁止」の標識です。一方通行の出口などに設置され、車両（自動車・原付・軽車両）の進入を禁止しますが、歩行者は通行できます。', 'sign_no_entry');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', 'この標識は「通行止め」を表しており、歩行者も車もすべて通行することができない。', '["○（正しい）","×（誤り）"]', 0, 1, '白い丸に赤い×印は「通行止め」で、歩行者・車両・路面電車すべてが通行禁止です。', 'sign_no_thoroughfare');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', 'この標識がある道路では、自動車や原動機付自転車は通行できないが、自転車（軽車両）は通行することができる。', '["○（正しい）","×（誤り）"]', 1, 2, '「車両通行止め」の標識です。自動車・原付だけでなく、自転車などの軽車両も含むすべての「車両」が通行禁止となります（歩行者は可）。', 'sign_no_cars');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', 'この標識がある場所では、人の乗り降りのための停止であっても禁止されている。', '["○（正しい）","×（誤り）"]', 0, 1, '青地に赤い×印は「駐停車禁止」です。駐車だけでなく、人の乗り降りや5分以内の荷物の積み下ろし等の「停車」も禁止されます。', 'sign_no_parking');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', 'この標識がある場所では、運転者がすぐに運転できる状態で5分以内の荷物の積み下ろしをするための停車であれば行うことができる。', '["○（正しい）","×（誤り）"]', 0, 2, '青地に赤い斜線1本は「駐車禁止」です。人の乗り降りや5分以内の荷物の積み下ろしなど「停車」にあたる停止は禁止されていません。', 'sign_no_park_only');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', 'この標識がある道路では、原動機付自転車も自動車と同じく時速40キロメートルまで出して走行することができる。', '["○（正しい）","×（誤り）"]', 1, 2, '最高速度の標識が「40」であっても、原動機付自転車の法定最高速度は30km/hであるため、30km/hを超えて走行することはできません。', 'sign_speed_40');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', 'この標識がある道路では、矢印の方向に向かって一方通行となるため、反対方向から進入することはできない。', '["○（正しい）","×（誤り）"]', 0, 1, '青い四角に白い矢印は「一方通行」の指示標識です。矢印の方向にのみ進むことができます。', 'sign_one_way');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', 'この標識がある交差点では、矢印の方向（直進）にしか進むことができず、右折や左折は禁止されている。', '["○（正しい）","×（誤り）"]', 0, 1, '青い丸に白い矢印は「指定方向外進行禁止」の規制標識です。矢印以外の方向への進行が禁止されます（一方通行の青い四角と混同しないこと）。', 'sign_designated_dir');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', 'この標識がある場所を通過する際、横断しようとする歩行者がいないことが明らかな場合でも、必ずその手前で一時停止しなければならない。', '["○（正しい）","×（誤り）"]', 1, 2, '横断歩道の標識です。横断する歩行者等がいないことが明らかな場合はそのまま通過できます。歩行者がいる・横断しようとしている場合は必ず一時停止が必要です。', 'sign_crosswalk');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', 'この標識がある道路を走行しているときは、交差する道路に一時停止の標識がなくても、自分の走行している道路が優先道路である。', '["○（正しい）","×（誤り）"]', 0, 2, '黄色いひし形に白い縁取りは「優先道路」を示す指示標識です。優先道路を通行しているときは交差道路の車両より優先されます。', 'sign_priority');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', 'この黄色いひし形の標識は、前方に踏切があることを知らせる警戒標識であり、踏切の直前では必ず一時停止しなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '「踏切あり」の警戒標識です。踏切を通過する際は、信号機がある場合を除き必ず直前で一時停止して安全を確認します。', 'sign_warn_rail');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', 'この標識がある場所では、前方に十字路交差点があることを知らせており、信号機がなければ必ず一時停止しなければならない。', '["○（正しい）","×（誤り）"]', 1, 2, '「十字路あり」の警戒標識は注意を促す標識であり、それ自体に一時停止の義務はありません（見通しが悪い場合などは徐行義務が生じます）。', 'sign_warn_cross');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_hazard', '【危険予測】昼間、見通しの悪い住宅街で前方に駐車車両があり、その陰からボールが転がり出てきました。このときの運転上の判断として適切な組み合わせはどれ？
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_hazard', '【危険予測】青信号の交差点で右折待ちをしています。対向車線には右折待ちの大型トラックが停車しており、その陰の見通しが悪い状態です。適切な判断の組み合わせはどれ？
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_hazard', '【危険予測】夜間、雨天の交差点を直進中です。対向車のヘッドライトがまぶしく、路面が濡れています。適切な判断の組み合わせはどれ？
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_hazard', '【危険予測】高速道路の本線車道を時速80kmで走行中、左前方の加速車線から合流しようとする車が見えました。適切な判断の組み合わせはどれ？
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_hazard', '【危険予測】片側1車線の道路で、前方のバス停に停車中の通学バスの側方を通過しようとしています。適切な判断の組み合わせはどれ？
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_hazard', '【危険予測】中央線のない生活道路（法定速度30km/h）を走行中、前方を走る自転車を追い越そうとしています。適切な判断の組み合わせはどれ？
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '運転適性検査（OD式やK式など）を受ける最大の目的として、最も適切なものはどれ？', '["自分の運転上のクセや性格傾向（焦りやすさ・慎重さ等）を知り、安全運転に活かすこと","不合格になると直ちに教習所を退校させられる選抜試験であること","学科試験の点数を加算するためのボーナス試験であること","視力や聴力のみを精密に測定する医学的検査であること"]', 0, 1, '運転適性検査に合否はありません。自分の長所や弱点（衝動性、注意配分の偏りなど）を客観的に把握し、事故を防ぐ運転に活かすことが目的です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '適性検査の性格・態度質問で「少しぐらいの違反ならバレなければ良いと思うことがある」といった質問に答える際、最も適切な姿勢はどれ？', '["自分を良く見せようと嘘をつくのではなく、素直かつ正直に回答する","すべて「いいえ」と書いて完璧な人格を装う","深く考えずすべて同じ選択肢に丸をつける","空欄のまま提出する"]', 0, 1, '適性検査には「虚偽発見尺度（自分を良く見せようとする回答を検出する質問）」が含まれているため、嘘をつくと正確な診断結果が出ず指導に活かせません。正直に回答するのが鉄則です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '適性検査の「図形抹消（同じ記号を素早く見つけて消す作業）」で測定されている主な能力はどれ？', '["正確な判断力と処理速度（注意力・集中力の持続）","美術的なデザインセンス","道路標識の暗記量","車のアクセル操作の巧みさ"]', 0, 1, '制限時間内に特定の記号を見落とさず正確にチェックする作業を通じて、運転に必要な「注意の正確さ」と「状況判断のスピード」のバランスを測定しています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '適性検査で「動作の正確さ」と「スピード」のバランスが問われる際、より安全運転につながりやすい意識はどれ？', '["速さだけを追ってミスを増やすより、一定のペースで確実・正確に処理すること","ミスを恐れすぎて1問に何十秒もかけ続けること","正確さは無視してとにかく一番速く終わらせること","途中で手が止まったらやり直すこと"]', 0, 2, '速さだけ優先して誤答が多いタイプは「慌てやすい・見落としやすい」傾向、逆に極端に遅いタイプは「判断に迷いやすい」傾向と評価されます。正確さを保ちつつテンポよく進めるのが理想です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '運転適性検査で「情緒の安定性」や「安全態度」が低いと診断された場合、教習中や運転時に心がけるべき対策はどれ？', '["イライラしたり焦ったりしやすい場面を自覚し、時間に余裕を持って深呼吸する習慣をつける","自分は運転に向いていないので一切練習しない","他の車に負けないよう常に強気で運転する","診断結果は見なかったことにして忘れる"]', 0, 1, '感情的・衝動的になりやすい傾向を知ったら、「急がない」「譲り合いの気持ちを持つ」など具体的な行動ルールを決めることで事故リスクを大きく下げられます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '適性検査の「反応速度・注意配分」テストにおいて、周囲の複数の情報に同時に気を配る力が試されるのは、実際の運転のどの場面に直結するか？', '["信号・歩行者・対向車・ミラーを同時に確認しながら交差点を通過する場面","自宅の駐車場でエンジンを切って降りた後","高速道路のサービスエリアで休憩しているとき","洗車機で車を洗っているとき"]', 0, 1, '運転中は1つの対象（例：前の車だけ）に視線が固着すると脇からの歩行者を見落とします。注意配分の広さを意識することが安全運転の要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '中央線や車両通行帯のない生活道路では、標識等で指定がない限り、法定最高速度は時速30kmである。', '["○（正しい）","×（誤り）"]', 0, 1, '2026年9月施行の改正道路交通法により、中央線等のない一般道路の法定最高速度は時速30kmに引き下げられました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '信号機が青色の灯火を表示している場合、自動車は他の交通に注意しながら、そのまま進行することができる。', '["○（正しい）","×（誤り）"]', 0, 1, '青信号は進行可能ですが、交差点内で停止するおそれがある場合や、歩行者等の安全を確認する義務は常にあります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '黄色の灯火の信号で、安全に停止できない場合を除き、停止位置で停止しなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '黄色信号は原則停止です。停止線で安全に止まれない場合に限り、交差点から速やかに出るために進行が許されます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '赤色の灯火の信号では、停止位置で停止しなければならないが、左折であればそのまま進行できる。', '["○（正しい）","×（誤り）"]', 1, 1, '赤信号は原則停止です。矢印信号がない限り、左折であっても停止位置で停止しなければなりません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '赤色の灯火の点滅信号がある場合、自動車は一時停止し、安全を確認した後に進行しなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '赤色の点滅信号は「一時停止」を意味します。必ず停止線で止まり、安全を確認してから進む必要があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '黄色い矢印の信号は、路面電車のみに対する信号であり、自動車は従う必要がない。', '["○（正しい）","×（誤り）"]', 0, 2, '黄色い矢印は路面電車専用の信号です。自動車はこれに従う必要はなく、通常の信号機に従います。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '警察官が手信号で腕を垂直に上げている場合、対面する交通に対しては赤信号と同じ意味を持つ。', '["○（正しい）","×（誤り）"]', 0, 2, '警察官が腕を垂直に上げているのは「停止信号」であり、対面する交通は赤信号と同様に停止しなければなりません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '黄色い灯火の点滅信号は、他の交通に注意して徐行して進まなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '黄色い点滅信号は「注意して進め」という意味です。徐行し、周囲の安全を確認しながら進行します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '自動車を運転する際は、常に周囲の交通状況に気を配り、思いやりと譲り合いの気持ちを持つことが大切である。', '["○（正しい）","×（誤り）"]', 0, 1, '運転者の心得として、法令遵守だけでなく、他者への配慮や譲り合いの精神は非常に重要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '自転車を追い越す際は、十分な側方間隔を空けるか、安全な速度で進行しなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '2026年4月施行の改正法により、自転車追い越し時の安全確保がより明確に義務化されました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '普通免許の仮免許試験は、17歳6か月以上であれば受験することができる。', '["○（正しい）","×（誤り）"]', 0, 2, '2026年4月施行の改正法により、受験資格が17歳6か月以上に引き下げられました。ただし交付は18歳からです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', 'マイナ免許証を保有している場合、従来のプラスチック製免許証を携帯する必要は全くない。', '["○（正しい）","×（誤り）"]', 1, 2, 'マイナ免許証のみ、従来免許証のみ、両方持ちの3択です。従来免許証を携帯しない場合はマイナ免許証が必須です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '信号機が故障している交差点では、信号機の表示に従う必要はないが、一時停止の標識があればそれに従う。', '["○（正しい）","×（誤り）"]', 0, 2, '信号機が消灯または故障している場合は、優先道路や標識、一時停止のルールに従って安全を確認します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '青色の矢印信号が出ている場合、その矢印の方向に進むことができるが、歩行者等の横断を妨げてはならない。', '["○（正しい）","×（誤り）"]', 0, 1, '矢印信号は進行を許可するものですが、横断中の歩行者や自転車の安全を優先しなければなりません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '警察官が手信号で腕を水平に上げている場合、その腕と平行する方向の交通は進むことができる。', '["○（正しい）","×（誤り）"]', 0, 2, '警察官の腕と平行する方向は進行可能（青信号相当）、対面する方向は停止信号（赤信号相当）です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '中央線のある一般道路の法定最高速度は、標識がない場合でも時速50kmである。', '["○（正しい）","×（誤り）"]', 1, 1, '中央線や車両通行帯のある一般道路の法定最高速度は時速60kmです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '自転車の交通違反に対して青切符制度が導入されたため、自転車は自動車と同じように免許証を提示する必要がある。', '["○（正しい）","×（誤り）"]', 1, 2, '青切符制度は導入されましたが、自転車は免許制ではないため、免許証の提示義務はありません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '交差点で右折しようとする際、対向車が直進してくる場合は、対向車の進行を妨げてはならない。', '["○（正しい）","×（誤り）"]', 0, 1, '右折車は直進車を優先しなければなりません。対向車の進行を妨げるような無理な右折は禁止です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '信号機のない交差点で、どちらが優先道路か不明な場合は、左方から来る車を優先しなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '優先道路が不明な交差点では、左方車優先の原則が適用されます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '免許証の交付は18歳から可能であるが、仮免許の練習は17歳6か月以上であれば指導員同乗のもとで可能である。', '["○（正しい）","×（誤り）"]', 0, 2, '2026年4月施行の改正法により、17歳6か月以上で仮免許の練習が可能となりました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '青色の矢印信号が出ているとき、右折車線にいる自動車は、右折だけでなく直進も可能である。', '["○（正しい）","×（誤り）"]', 1, 2, '矢印信号は、その矢印の方向にのみ進行可能です。右折矢印が出ているときに直進することはできません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '運転者は、疲労や病気などで正常な運転ができないおそれがあるときは、運転してはならない。', '["○（正しい）","×（誤り）"]', 0, 1, '運転者の心得として、心身の状態を良好に保つことは義務です。過労や体調不良時の運転は厳禁です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '赤信号で停止しているとき、後続車が急いでいる様子だったので、少し前に出て道を譲った。', '["○（正しい）","×（誤り）"]', 1, 2, '赤信号での停止位置は厳守です。後続車のために停止線を越えて進むことは信号無視となります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '自転車も車両の一種であるため、信号機が青色のときは、自動車と同様に進行することができる。', '["○（正しい）","×（誤り）"]', 0, 1, '自転車は軽車両であり、道路交通法上は車両として信号や標識に従う義務があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '警察官が手信号で腕を水平に上げているとき、その腕と対面する交通は停止しなければならない。', '["○（正しい）","×（誤り）"]', 0, 2, '警察官の腕と対面する方向は、赤信号と同じ停止の合図です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '生活道路（中央線なし）において、歩行者が横断しようとしているときは、必ず一時停止して歩行者の通行を妨げないようにしなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '横断歩道や生活道路での歩行者優先は道路交通法の鉄則です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', 'マイナ免許証は、従来の免許証と異なり、更新手続きをオンラインで行うことができない。', '["○（正しい）","×（誤り）"]', 1, 2, 'マイナ免許証の導入により、一定の条件下でオンライン講習や更新手続きが可能となっています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '黄色信号で交差点内にすでに入っている場合は、そのまま速やかに交差点から出なければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '交差点内で黄色信号になった場合は、他の交通の妨げにならないよう速やかに交差点を出るのが正解です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '16歳以上の自転車利用者が交通違反をした場合、青切符による反則金の納付が求められることがある。', '["○（正しい）","×（誤り）"]', 0, 2, '2026年4月施行の改正法により、16歳以上の自転車違反に青切符制度が適用されます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '信号機が青色であっても、交差点が混雑していてその先に進むと交差点内で停止する可能性があるときは、交差点に入ってはならない。', '["○（正しい）","×（誤り）"]', 0, 1, '交差点内での停止は渋滞の原因となり、他の交通を妨げるため、進入禁止です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '「一時停止」の標識がある場所では、停止線の直前で停止し、安全を確認しなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '一時停止の標識がある場所では、停止線がある場合はその直前で、ない場合は交差点の直前で確実に停止し、安全を確認する義務があります。', 'sign_stop');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '「徐行」の標識がある場所では、時速10km以下で走行しなければならない。', '["○（正しい）","×（誤り）"]', 1, 2, '徐行とは、すぐに停止できる速度（ブレーキを踏んでから数メートル以内で止まれる速度）のことです。時速10km以下という決まりはありません。', 'sign_slow');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '「車両進入禁止」の標識がある道路には、自転車や原動機付自転車も進入してはならない。', '["○（正しい）","×（誤り）"]', 0, 1, '車両進入禁止は、すべての車両（自転車や原付を含む）の進入を禁止する標識です。歩行者は対象外ですが、車両は進入できません。', 'sign_no_entry');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '「通行止め」の標識がある道路は、歩行者も通行することができない。', '["○（正しい）","×（誤り）"]', 1, 2, '通行止めは「車両」の通行を禁止する標識です。歩行者は通行することができます。ひっかけ問題として頻出です。', 'sign_no_thoroughfare');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '「車両通行止め」の標識がある道路には、軽車両である自転車も進入してはならない。', '["○（正しい）","×（誤り）"]', 0, 1, '車両通行止めは、自転車を含むすべての車両の通行を禁止しています。軽車両も車両に含まれるため、進入は禁止です。', 'sign_no_cars');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '「駐車禁止」の標識がある場所では、人の乗り降りのための短時間の停車も禁止されている。', '["○（正しい）","×（誤り）"]', 1, 2, '駐車禁止の場所でも、人の乗り降りのための停車は認められています。荷物の積み下ろしなどの「停車」も可能です。', 'sign_no_parking');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '「駐停車禁止」の標識がある場所では、運転者が車から離れていなくても停車してはならない。', '["○（正しい）","×（誤り）"]', 0, 1, '駐停車禁止の場所では、たとえ運転者が車内にいてすぐに動かせる状態であっても、停車（および駐車）は一切禁止されています。', 'sign_no_park_only');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '中央線や車両通行帯のない生活道路において、標識がない場合の法定最高速度は時速40kmである。', '["○（正しい）","×（誤り）"]', 1, 2, '2026年9月施行の改正法により、中央線等のない生活道路の法定最高速度は時速30kmに変更されました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '「指定方向外進行禁止」の標識がある交差点では、矢印以外の方向へ進んではならない。', '["○（正しい）","×（誤り）"]', 0, 1, '指定方向外進行禁止は、矢印で示された方向以外への進行を禁じるものです。指定された方向へ進まなければなりません。', 'sign_designated_dir');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '「横断歩道」の標識がある場所では、歩行者がいなくても必ず一時停止しなければならない。', '["○（正しい）","×（誤り）"]', 1, 2, '横断歩道に歩行者がいるかいないか明らかでない場合は停止できる速度で近づきますが、歩行者がいないことが明らかなら徐行で通過可能です。', 'sign_crosswalk');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '「優先道路」の標識がある道路を通行している場合、交差点で他の道路から来る車両に対して優先権がある。', '["○（正しい）","×（誤り）"]', 0, 1, '優先道路の標識がある場合、その道路を通行する車両は交差点において優先権を持ちます。ただし、安全確認は必須です。', 'sign_priority');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '「踏切あり」の警戒標識がある場所では、踏切の手前で一時停止し、窓を開けて音を聞くなどして安全を確認しなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '踏切の手前では必ず一時停止し、目と耳で安全を確認する義務があります。これは非常に重要な安全確認事項です。', 'sign_warn_rail');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '「学校、幼稚園、保育所等あり」の警戒標識がある場所では、必ず時速20km以下で走行しなければならない。', '["○（正しい）","×（誤り）"]', 1, 2, 'この標識は注意を促すためのもので、特定の速度制限を課すものではありません。周囲の状況に応じて注意して走行します。', 'sign_warn_school');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '「すべりやすい」の警戒標識がある場所では、急ブレーキや急ハンドルを避け、慎重に運転する。', '["○（正しい）","×（誤り）"]', 0, 1, '路面が滑りやすい場所では、タイヤのグリップを失わないよう、操作を丁寧に行う必要があります。', 'sign_warn_slippery');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '「最高速度30キロ」の規制標識がある道路では、原動機付自転車も時速30kmを超えて走行してはならない。', '["○（正しい）","×（誤り）"]', 0, 1, '最高速度の規制標識は、すべての車両に適用されます。原付であっても標識の速度を超えて走行することはできません。', 'sign_speed_30');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '「一方通行」の標識がある道路では、道路の右側を通行しなければならない。', '["○（正しい）","×（誤り）"]', 1, 2, '一方通行であっても、車両は原則として道路の左側を通行しなければなりません。右側通行は認められていません。', 'sign_one_way');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '補助標識に「ここから」とある場合、その標識の位置から規制が始まることを示している。', '["○（正しい）","×（誤り）"]', 0, 1, '「ここから」という補助標識は、その地点から規制が開始されることを示します。反対に「ここまで」は規制の終了を示します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '「最高速度50キロ」の標識がある道路で、追い越しのために一時的に時速60kmまで加速することは許される。', '["○（正しい）","×（誤り）"]', 1, 2, '追い越し中であっても、法定速度や標識による最高速度を超えて走行することは禁止されています。', 'sign_speed_50');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '「十字路交差点あり」の警戒標識は、交差点があることを予告するものである。', '["○（正しい）","×（誤り）"]', 0, 1, '警戒標識は、前方に注意すべき道路状況があることを事前に知らせるためのものです。十字路の存在を予告しています。', 'sign_warn_cross');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '「T字路交差点あり」の警戒標識がある場所では、必ず一時停止しなければならない。', '["○（正しい）","×（誤り）"]', 1, 2, '警戒標識は注意を促すものであり、それ自体に一時停止の義務はありません。ただし、安全確認は必須です。', 'sign_warn_t');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '道路標示の「停止線」は、交差点等で一時停止すべき位置を示すものである。', '["○（正しい）","×（誤り）"]', 0, 1, '停止線は、信号や一時停止の標識に従って停止すべき位置を示す道路標示です。必ずこの線の手前で停止します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '「最高速度40キロ」の標識がある道路で、原動機付自転車は時速30kmまでしか出せないため、時速30kmで走行した。', '["○（正しい）","×（誤り）"]', 0, 2, '原付の法定最高速度は時速30kmです。標識が40kmであっても、車両自体の制限速度である30kmを守る必要があります。', 'sign_speed_40');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '「駐車禁止」の標識の下に「日曜・休日を除く」という補助標識がある場合、日曜日は駐車してもよい。', '["○（正しい）","×（誤り）"]', 0, 1, '補助標識で除外されている日時や条件は、規制の対象外となります。したがって、日曜日は駐車可能です。', 'sign_no_parking');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '「追い越し禁止」の標識がある場所では、自転車を追い越すことも禁止されている。', '["○（正しい）","×（誤り）"]', 1, 2, '追い越し禁止の標識は、自動車や原付を追い越すことを禁止するものです。自転車などの軽車両は追い越すことができます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '「車両通行帯」がある道路では、原則として左側の通行帯を通行しなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '車両通行帯がある道路では、左側の通行帯を通行するのが原則です。右側は追い越しや右折のための通行帯です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '「安全地帯」の標識がある場所では、歩行者がいなくても徐行しなければならない。', '["○（正しい）","×（誤り）"]', 1, 2, '安全地帯のそばを通る際、歩行者がいる場合は徐行が必要ですが、歩行者がいない場合は徐行の義務はありません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '「追い越し禁止」の標識がある場所でも、前方の車両が原動機付自転車であれば追い越してもよい。', '["○（正しい）","×（誤り）"]', 1, 2, '追い越し禁止の場所では、原付であっても追い越すことは禁止されています。追い越してよいのは自転車等の軽車両のみです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '「最高速度」の標識がない一般道路（中央線がある）の法定最高速度は時速60kmである。', '["○（正しい）","×（誤り）"]', 0, 1, '中央線がある一般道路の法定最高速度は時速60kmです。生活道路（中央線なし）の30kmと混同しないよう注意してください。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '「駐停車禁止」の標識がある場所では、故障で動けなくなった場合を除き、いかなる理由でも停車してはならない。', '["○（正しい）","×（誤り）"]', 0, 1, '駐停車禁止場所での停車は厳禁です。ただし、故障や交通渋滞など、やむを得ない事情がある場合は例外とされます。', 'sign_no_park_only');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '補助標識で「8-20」と書かれている場合、その規制は午前8時から午後8時までの間に行われる。', '["○（正しい）","×（誤り）"]', 0, 1, '補助標識の数字は時間を表します。8-20は午前8時から午後8時（20時）までを指します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '車両通行帯のない道路では、道路の左側に寄って通行しなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '道路交通法第18条により、車両通行帯のない道路では、車両は道路の左側に寄って通行しなければなりません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '中央線が引かれている道路で、追い越しをするために一時的に中央線を越えて右側を通行することは禁止されている。', '["○（正しい）","×（誤り）"]', 1, 2, '中央線が黄色であっても、追い越しのために右側にはみ出すことは禁止ですが、白の実線や破線であれば追い越しのために右側を通行できます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '路線バス専用レーンを通行している際、左折しようとする場合は、交差点の直前でそのレーンに入ることができる。', '["○（正しい）","×（誤り）"]', 0, 2, 'バス専用レーンは原則通行禁止ですが、左折や工事等のやむを得ない理由がある場合は、交差点の直前でレーンに入ることができます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '軌道敷内を通行できるのは、右折や横断、転回をするために必要な場合のみである。', '["○（正しい）","×（誤り）"]', 0, 2, '軌道敷内は原則通行禁止ですが、右左折や横断、転回のために必要な場合は通行が認められています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '車両通行帯が3つ以上ある道路では、速度の速い車が最も右側の通行帯を通行しなければならない。', '["○（正しい）","×（誤り）"]', 1, 2, '最も右側の通行帯は追い越しのために空けておく必要があります。速度に関わらず、追い越しが終わったら左側の通行帯に戻る義務があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', 'バス優先レーンを通行中、後方から路線バスが接近してきた場合は、速やかにそのレーンから出なければならない。', '["○（正しい）","×（誤り）"]', 0, 1, 'バス優先レーンは一般車も通行可能ですが、路線バスが接近してきた場合は、バスの通行を妨げないよう速やかにレーンから出る必要があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '中央線が黄色い実線で示されている道路では、追い越しのためにその線を越えて右側を通行してはならない。', '["○（正しい）","×（誤り）"]', 0, 1, '黄色い実線の中央線は「追い越し禁止」の場所を示しており、はみ出して右側を通行することは禁止されています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '中央線や車両通行帯のない生活道路では、法定最高速度は時速60kmである。', '["○（正しい）","×（誤り）"]', 1, 2, '2026年9月施行の改正法により、中央線や車両通行帯のない一般道路（生活道路）の法定最高速度は時速30kmに引き下げられました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '自転車が通行している道路を追い越す際は、自転車との間に十分な側方間隔を空けるか、安全な速度で進行しなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '2026年4月施行の改正法により、自転車の安全確保のため、追い越し時の側方間隔保持と安全速度での進行が義務付けられました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '車両通行帯がある道路では、原則としてどの通行帯を通行してもよい。', '["○（正しい）","×（誤り）"]', 1, 2, '車両通行帯がある道路では、原則として左側の通行帯から順に通行しなければなりません。右側の通行帯は追い越し用です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '軌道敷内を通行中、路面電車が接近してきた場合は、直ちに軌道敷外へ出なければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '軌道敷内を通行中に路面電車が接近してきた場合は、路面電車の通行を妨げないよう、直ちに軌道敷外へ出る必要があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '一方通行の道路では、道路の右側を通行してもよい。', '["○（正しい）","×（誤り）"]', 1, 2, '一方通行であっても、車両は原則として道路の左側に寄って通行しなければなりません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '原動機付自転車は、車両通行帯がある道路でも、常に一番左側の通行帯を通行しなければならない。', '["○（正しい）","×（誤り）"]', 0, 2, '原動機付自転車は、車両通行帯がある道路では、原則として一番左側の通行帯を通行しなければなりません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '緊急自動車が接近してきたときは、交差点付近では交差点を避けて左側に寄って一時停止しなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '緊急自動車の接近時は、交差点付近では左側に寄って一時停止し、進路を譲る必要があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '車両通行帯のない道路で、右折するために道路の中央に寄ることは禁止されている。', '["○（正しい）","×（誤り）"]', 1, 2, '右折をするために道路の中央に寄ることは、右折の準備として認められています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', 'バス専用レーンは、タクシーであれば客待ちのために停車してもよい。', '["○（正しい）","×（誤り）"]', 1, 2, 'バス専用レーンは、路線バス等の指定車両以外は通行禁止です。タクシーであっても客待ちの停車は認められません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '追い越しをする際、前車が右折の合図をしているときは、その右側を追い越してはならない。', '["○（正しい）","×（誤り）"]', 0, 1, '右折の合図をしている車の右側を追い越すことは、二重右折などの危険があるため禁止されています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '車両通行帯が設けられた道路で、追い越しをするために左側の通行帯から右側の通行帯へ変更することは違反である。', '["○（正しい）","×（誤り）"]', 1, 2, '追い越しのために通行帯を変更することは認められています。ただし、安全確認と合図が必要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '路面電車が停留所に停車しており、乗客の乗り降りのためにドアが開いているときは、安全な間隔を空けて徐行して通過しなければならない。', '["○（正しい）","×（誤り）"]', 1, 2, '路面電車が停留所に停車中で乗客が乗り降りしているときは、安全地帯がある場合を除き、後方で一時停止しなければなりません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '仮免許の練習で走行する場合、指導員が同乗していれば、高速道路を通行することができる。', '["○（正しい）","×（誤り）"]', 1, 2, '仮免許練習中の車両は、高速道路や自動車専用道路を通行することは禁止されています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '道路の左側に路側帯がある場合、その路側帯を通行してはならない。', '["○（正しい）","×（誤り）"]', 0, 1, '路側帯は歩行者のための場所であり、車両が通行することは禁止されています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '一方通行の道路では、追い越しをするために右側を通行してもよい。', '["○（正しい）","×（誤り）"]', 0, 2, '一方通行の道路では、追い越しのために右側を通行することが認められています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '車両通行帯のある道路で、左側の通行帯が工事で塞がっている場合、右側の通行帯を通行できる。', '["○（正しい）","×（誤り）"]', 0, 1, '工事や障害物があるなど、やむを得ない理由がある場合は、右側の通行帯を通行することができます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '自転車専用通行帯がある道路では、普通自動車は自転車専用通行帯を通行してはならない。', '["○（正しい）","×（誤り）"]', 0, 1, '自転車専用通行帯は自転車のみが通行できる場所であり、自動車は通行禁止です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '中央線が白の破線である場合、追い越しのために中央線を越えて右側を通行できる。', '["○（正しい）","×（誤り）"]', 0, 1, '白の破線の中央線は、追い越し等のために右側へはみ出すことが認められています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '路線バス優先レーンを通行中、後方から路線バスが接近してきた場合、直ちにそのレーンから出なければならない。', '["○（正しい）","×（誤り）"]', 0, 1, 'バス優先レーンでは、路線バスが接近してきたらバスの通行を妨げないよう速やかにレーンから出る必要があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '軌道敷内を通行中、後方から路面電車が接近してきた場合、直ちに軌道敷外へ出なければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '路面電車の通行を妨げないよう、接近してきたら直ちに軌道敷外へ出る義務があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '車両通行帯のない道路で、左側に寄って通行しているとき、後続車が追い越そうとしている場合は、速度を上げて追い越しを妨げてはならない。', '["○（正しい）","×（誤り）"]', 0, 1, '追い越しを妨害する行為は禁止されています。追い越されるときは速度を上げず、進路を譲る必要があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '普通免許の受験資格は、18歳以上でなければならない。', '["○（正しい）","×（誤り）"]', 1, 2, '2026年4月施行の改正法により、受験資格は17歳6か月以上となりました（免許交付は18歳から）。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '交差点で右折する際、対向車が直進してくる場合は、対向車の進行を妨げてはならない。', '["○（正しい）","×（誤り）"]', 0, 1, '右折車は直進車や左折車の進行を妨げてはならないという優先関係が道路交通法で定められています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '交差点を右折するときは、あらかじめ道路の中央に寄り、交差点の中心のすぐ内側を徐行して通行しなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '右折時の基本ルールです。対向車や横断歩行者に注意し、中心の内側を通ることで安全を確保します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '信号機のない交差点で、優先道路を通行している場合は、交差点に入る前に一時停止して安全を確認しなければならない。', '["○（正しい）","×（誤り）"]', 1, 2, '優先道路を通行している場合は、徐行の義務はありません。ただし、安全確認は必要ですが、一時停止の義務はありません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '左折するときは、あらかじめ道路の左端に寄り、交差点の側端に沿ってゆっくりと曲がらなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '左折時の基本です。巻き込み事故を防ぐため、左端に寄せて側端に沿って通行します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '見通しのきかない交差点では、信号機や一時停止の規制がない場合でも、必ず一時停止しなければならない。', '["○（正しい）","×（誤り）"]', 1, 2, '見通しのきかない交差点では「徐行」が義務ですが、一時停止の義務はありません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '交通整理の行われていない交差点で、道幅が同じ場合、左方から来る車が優先される。', '["○（正しい）","×（誤り）"]', 0, 2, '交差点の優先関係の基本です。左方優先の原則に従います。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '中央線や車両通行帯のない道路では、交差点付近であっても追い越しをしてはならない。', '["○（正しい）","×（誤り）"]', 1, 2, '交差点内やその手前30m以内は追い越し禁止ですが、中央線の有無だけで一律禁止されるわけではありません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '信号機のない交差点で、一時停止の標識がある場合は、停止線の直前で一時停止し、安全を確認しなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '一時停止の標識がある場所では、停止線の直前での完全停止が義務付けられています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '交差点を右折する際、横断歩道を渡っている歩行者がいたが、車の方が先に通過できると判断したためそのまま進行した。', '["○（正しい）","×（誤り）"]', 1, 1, '横断歩行者が優先です。歩行者の通行を妨げるような進行は絶対にしてはいけません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '環状交差点（ラウンドアバウト）では、環状交差点内を通行している車が優先である。', '["○（正しい）","×（誤り）"]', 0, 2, '環状交差点では、交差点内を通行中の車が優先されます。進入する車は譲らなければなりません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '信号機のない交差点で、明らかに幅の広い道路と交差している場合、幅の広い道路を通行している車が優先される。', '["○（正しい）","×（誤り）"]', 0, 2, '道幅が明らかに広い道路を通行している車が優先です。左方優先よりも優先されます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '交差点で左折する際、後方から自転車が直進してくるのが見えたが、そのまま左折して追い抜いた。', '["○（正しい）","×（誤り）"]', 1, 2, '左折時の巻き込み事故を防ぐため、自転車の進路を妨げないよう注意が必要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '交差点付近で緊急自動車が接近してきたときは、交差点内であっても直ちに停止しなければならない。', '["○（正しい）","×（誤り）"]', 1, 2, '交差点内では停止せず、交差点を避けて左側に寄って停止します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '見通しの悪い交差点で、徐行の標識がない場合でも、徐行しなければならない。', '["○（正しい）","×（誤り）"]', 0, 2, '見通しの悪い交差点は、標識の有無に関わらず徐行義務があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '交差点を右折する際、対向車が右折しようとしている場合、お互いに交差点の中心の内側を通って右折する。', '["○（正しい）","×（誤り）"]', 0, 2, '対向車同士が右折する場合、両車とも中心の内側を通るのが原則です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '信号機のない交差点で、優先道路を通行している場合、交差する道路から来る車に対して徐行する必要はない。', '["○（正しい）","×（誤り）"]', 0, 2, '優先道路を走行中は徐行義務はありません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '交差点で左折する際、あらかじめ道路の左端に寄るが、二輪車が左側をすり抜けてくる可能性があるため、幅を空けて左折した。', '["○（正しい）","×（誤り）"]', 1, 2, '左折時は左端に寄るのがルールです。隙間を空けると二輪車の巻き込みを誘発するため危険です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '信号機のある交差点で、青信号であっても、交差点内で停止する恐れがあるときは進入してはならない。', '["○（正しい）","×（誤り）"]', 0, 1, '交差点内での立ち往生を防ぐため、前方が混雑している場合は進入してはいけません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '交差点で右折する際、対向車線が渋滞していたため、対向車が道を譲ってくれると判断し、確認せずに右折した。', '["○（正しい）","×（誤り）"]', 1, 2, '対向車の陰から直進車やバイクが来る可能性があるため、必ず安全確認が必要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '交差点において、信号機が黄色を表示している場合、停止位置で安全に停止できない場合を除き、停止しなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '黄色の信号は原則停止です。停止位置で安全に止まれない場合のみ進行できます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '交差点で右折する際、対向車が直進してくるが、距離が十分あると判断したため、急いで右折した。', '["○（正しい）","×（誤り）"]', 1, 2, '直進車優先の原則に加え、距離の判断ミスは重大事故に繋がるため、無理な右折は禁物です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '交差点付近で、前方の車が右折するために減速したので、左側から追い越した。', '["○（正しい）","×（誤り）"]', 1, 2, '右折しようとしている車の左側を追い越すことは禁止されています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '信号機のない交差点で、一時停止の標識がある場合、停止線の手前で停止し、安全を確認してから発進した。', '["○（正しい）","×（誤り）"]', 0, 1, '一時停止の正しい手順です。停止線で止まり、左右の安全確認を徹底します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '交差点で左折する際、横断歩道に歩行者がいなかったので、徐行せずに左折した。', '["○（正しい）","×（誤り）"]', 1, 2, '交差点での左折は、歩行者の有無に関わらず徐行が義務付けられています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '交差点で右折する際、対向車線から左折してくる車がある場合、右折車が優先される。', '["○（正しい）","×（誤り）"]', 1, 2, '右折車と左折車では、左折車が優先されるのが原則です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '信号機のない交差点で、道幅が同じ場合、路面電車が通行しているときは、路面電車が優先される。', '["○（正しい）","×（誤り）"]', 0, 2, '路面電車は軌道敷内を通行するため、一般車両よりも優先されます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '交差点で右折する際、対向車が右折の合図を出していたので、自分の車が先に右折した。', '["○（正しい）","×（誤り）"]', 0, 2, '対向車同士が右折する場合、お互いに進行を妨げない範囲で通行可能です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '交差点付近で、緊急自動車が接近してきたので、交差点の中央で停止した。', '["○（正しい）","×（誤り）"]', 1, 2, '交差点の中央で停止すると緊急自動車の通行を妨げます。交差点を避けて左側に寄るのがルールです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '交差点で左折する際、後方から来る自転車に注意するため、左側の安全確認を徹底した。', '["○（正しい）","×（誤り）"]', 0, 1, '左折時の巻き込み確認は必須です。目視での安全確認が重要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '踏切を通過する際は、変速操作（ギアチェンジ）をせず、低速ギアのまま一気に通過しなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '踏切内でのエンストや変速ミスによる立ち往生を防ぐため、進入前に低速ギアに入れ、通過し終わるまで変速操作をしてはいけません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '横断歩道に近づいたとき、歩行者がいるかどうかが明らかでないときは、横断歩道の手前で停止できるように速度を落として進行しなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '横断歩道に歩行者がいるか不明な場合は、停止できる速度で接近する義務があります。これを「停止可能速度」といいます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '安全地帯に歩行者がいる場合、その横を通過するときは、徐行しなければならない。', '["○（正しい）","×（誤り）"]', 1, 2, '安全地帯に歩行者がいる場合、徐行の義務はありません。ただし、歩行者に注意して安全な間隔を空けて通行する必要があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '踏切の手前で停止したときは、窓を開けて目と耳で安全を確認しなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '踏切での安全確認は、目視だけでなく音を聞くことも重要です。窓を開けて警報機の音や列車の接近音を確認することが義務付けられています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '横断歩道のない交差点で、歩行者が横断しているときは、一時停止して歩行者の通行を妨げてはならない。', '["○（正しい）","×（誤り）"]', 0, 2, '横断歩道の有無に関わらず、交差点で横断中の歩行者がいる場合は、その通行を妨げてはいけません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '自転車横断帯を自転車が横断しようとしているときは、一時停止してその通行を妨げてはならない。', '["○（正しい）","×（誤り）"]', 0, 1, '自転車横断帯も横断歩道と同様に、自転車が横断しようとしているときは一時停止し、通行を妨げてはいけません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '踏切内で故障して動かなくなったときは、ただちに発炎筒や停止表示板などで列車に合図を送らなければならない。', '["○（正しい）","×（誤り）"]', 0, 2, '踏切内で動けなくなった場合は、列車に異常を知らせるのが最優先です。発炎筒等で合図し、二次被害を防ぎます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '横断歩道の手前で停止している車がある場合、その横を通過する前に一時停止しなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '横断歩道の手前で停止している車がある場合、歩行者が隠れている可能性があるため、追い越す前に必ず一時停止しなければなりません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '安全地帯がない道路で、路面電車が停車している場合、乗降客がいても徐行して通過すればよい。', '["○（正しい）","×（誤り）"]', 1, 2, '安全地帯がなく、乗降客がいる場合は、路面電車の後方で一時停止し、乗降客がいなくなるまで待たなければなりません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '踏切を通過する際、前の車が踏切の向こう側で停止したため、自分の車が踏切内に残ってしまう可能性があるときは、踏切に入ってはならない。', '["○（正しい）","×（誤り）"]', 0, 1, '踏切内での立ち往生は重大事故につながります。前方の交通状況を確認し、確実に通過できる場合のみ進入します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '横断歩道に近づいたとき、歩行者が渡ろうとしていることが明らかな場合は、横断歩道の手前で一時停止しなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '歩行者が横断しようとしていることが明らかな場合、一時停止して歩行者の通行を妨げないようにしなければなりません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '自転車が横断歩道を渡っているときは、歩行者と同様に一時停止して通行を妨げないようにしなければならない。', '["○（正しい）","×（誤り）"]', 1, 3, '自転車が横断歩道を渡っている場合、その自転車に対して一時停止義務はありません。ただし、接触しないよう注意が必要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '踏切の警報機が鳴り始めたら、急いで通過しなければならない。', '["○（正しい）","×（誤り）"]', 1, 1, '警報機が鳴り始めたら、踏切内に入ってはいけません。すでに踏切内にある場合は、速やかに通過します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '横断歩道に歩行者がいないことが明らかな場合でも、横断歩道の手前では必ず一時停止しなければならない。', '["○（正しい）","×（誤り）"]', 1, 2, '歩行者がいないことが明らかな場合は、一時停止の義務はありません。徐行して通過します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '安全地帯の周囲を通行するときは、歩行者がいなくても徐行しなければならない。', '["○（正しい）","×（誤り）"]', 1, 2, '安全地帯の周囲を通行する場合、徐行義務はありません。ただし、歩行者に注意して通行します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '踏切の遮断機が降りかけているときは、無理に通過してはならない。', '["○（正しい）","×（誤り）"]', 0, 1, '遮断機が降りかけている踏切への進入は禁止されています。無理な通過は大変危険です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '横断歩道のない場所で歩行者が道路を横断している場合、車は必ず一時停止しなければならない。', '["○（正しい）","×（誤り）"]', 1, 2, '横断歩道のない場所では、歩行者の通行を妨げないように注意して通行しますが、必ずしも一時停止の義務はありません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '踏切を通過する際は、対向車が来ないことを確認すれば、中央線をはみ出して通行してもよい。', '["○（正しい）","×（誤り）"]', 1, 2, '踏切内での追い越しや、中央線をはみ出しての通行は禁止されています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '横断歩道に近づいたとき、歩行者が渡り終えた直後であれば、徐行せずに通過してもよい。', '["○（正しい）","×（誤り）"]', 0, 2, '歩行者が完全に渡り終えたことが確認できれば、徐行義務は解除されます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '安全地帯に歩行者がいる場合、その横を通過するときは、一時停止しなければならない。', '["○（正しい）","×（誤り）"]', 1, 2, '安全地帯に歩行者がいる場合、徐行や一時停止の義務はありません。安全な間隔を空けて通行します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '踏切で停止したときは、ギアをニュートラルに入れて待機するのが安全である。', '["○（正しい）","×（誤り）"]', 1, 2, '踏切内でエンストした際にすぐ発進できるよう、ギアはロー（1速）に入れておくのが基本です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '横断歩道の手前で停止している車がある場合、その横を通過する際、歩行者がいないことが確認できれば一時停止しなくてもよい。', '["○（正しい）","×（誤り）"]', 1, 2, '横断歩道の手前で停止している車がある場合は、歩行者の有無に関わらず、追い越す前に必ず一時停止しなければなりません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '踏切の警報機が鳴っていない場合でも、一時停止して安全を確認しなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '警報機の有無に関わらず、踏切では必ず一時停止し、左右の安全を確認しなければなりません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '横断歩道や自転車横断帯に近づいたとき、歩行者や自転車がいないことが明らかな場合は、速度を落とさずに通過してもよい。', '["○（正しい）","×（誤り）"]', 1, 2, '歩行者等がいないことが明らかな場合でも、横断歩道等に近づくときは、停止できる速度で進行しなければなりません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '安全地帯のそばを通るときは、歩行者の有無に関わらず、徐行しなければならない。', '["○（正しい）","×（誤り）"]', 1, 2, '安全地帯のそばを通る際、徐行義務はありません。ただし、歩行者に注意して通行します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '踏切を通過する際、前の車に続いて通過する場合でも、踏切の手前で一時停止しなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '前の車に続いて通過する場合でも、踏切では必ず一時停止して安全を確認しなければなりません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '横断歩道で歩行者が横断しているときは、車は一時停止して歩行者の通行を妨げてはならない。', '["○（正しい）","×（誤り）"]', 0, 1, '横断歩道は歩行者優先です。横断中の歩行者がいる場合は、必ず一時停止して通行を妨げてはいけません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '自転車横断帯を通行する自転車がいない場合でも、自転車横断帯の手前では一時停止しなければならない。', '["○（正しい）","×（誤り）"]', 1, 2, '自転車が横断しようとしていない場合は、一時停止の義務はありません。徐行して通過します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '踏切内で車が故障したときは、同乗者を避難させた後、速やかに非常ボタンを押すか発炎筒で合図する。', '["○（正しい）","×（誤り）"]', 0, 1, '踏切内での故障時は、まず人命の安全を確保し、次に列車への合図を行うのが正しい手順です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '中央線や車両通行帯のない一般道路では、標識や標示による指定がない限り、法定最高速度は時速30キロメートルである。', '["○（正しい）","×（誤り）"]', 0, 1, '2026年9月施行の改正道路交通法により、中央線等のない生活道路の法定最高速度は時速30kmに引き下げられました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '中央線がある一般道路であっても、標識等で指定がない場合は時速30キロメートルで走行しなければならない。', '["○（正しい）","×（誤り）"]', 1, 1, '中央線がある一般道路の法定最高速度は時速60kmです。生活道路（中央線なし）の30kmと混同しないよう注意が必要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '原動機付自転車の法定最高速度は、道路の種類に関わらず時速30キロメートルである。', '["○（正しい）","×（誤り）"]', 0, 1, '原動機付自転車は、道路の法定速度に関わらず、車両自体の構造上の制限として時速30kmが上限と定められています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '停止距離は、空走距離と制動距離を合わせたものである。', '["○（正しい）","×（誤り）"]', 0, 1, '停止距離＝空走距離（危険を感じてブレーキを踏むまでの距離）＋制動距離（ブレーキが効き始めてから止まるまでの距離）です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '時速60キロメートルで走行している場合、空走距離は制動距離よりも長くなる。', '["○（正しい）","×（誤り）"]', 1, 2, '速度が上がるほど、制動距離は速度の2乗に比例して急激に伸びるため、時速60kmでは制動距離の方が長くなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '前車との車間距離は、速度が速くなるほど長く取る必要がある。', '["○（正しい）","×（誤り）"]', 0, 1, '速度が速いと停止距離が長くなるため、追突を防ぐためにはより長い車間距離を確保しなければなりません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '雨の日は路面が滑りやすいため、乾燥した路面に比べて制動距離が短くなる。', '["○（正しい）","×（誤り）"]', 1, 1, '雨の日はタイヤと路面の摩擦力が低下するため、ブレーキが効きにくくなり、制動距離は長くなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '自動車が自転車を追い越す際は、十分な側方間隔を空けるか、安全な速度で進行しなければならない。', '["○（正しい）","×（誤り）"]', 0, 2, '2026年4月施行の改正法により、自転車保護の観点から追い越し時の安全確保がより厳格に義務付けられました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '時速30キロメートルの道路で、原動機付自転車が時速40キロメートルで走行することは法令違反である。', '["○（正しい）","×（誤り）"]', 0, 1, '原付の最高速度は時速30kmです。道路の制限速度がそれ以上であっても、原付は30kmを超えて走行できません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '空走距離は、運転者の疲労や飲酒によって短くなることがある。', '["○（正しい）","×（誤り）"]', 1, 2, '疲労や飲酒は反応を遅らせるため、ブレーキを踏むまでの時間（空走時間）が長くなり、結果として空走距離は長くなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '交通量の多い市街地では、法定速度以内であれば車間距離を詰めて走行してもよい。', '["○（正しい）","×（誤り）"]', 1, 1, 'どんな状況でも、急ブレーキに対応できる安全な車間距離を確保する義務があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '普通免許の仮免許は、17歳6か月以上であれば受験することができる。', '["○（正しい）","×（誤り）"]', 0, 2, '2026年4月施行の改正により、受験資格が17歳6か月以上に引き下げられました（免許交付は18歳から）。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '中央線のある道路で、追い越しのために右側部分にはみ出すことは禁止されている。', '["○（正しい）","×（誤り）"]', 1, 2, '中央線が黄色い実線であれば追い越しのためのはみ出しは禁止ですが、白の破線であれば追い越しのためのはみ出しは可能です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '停止距離は、速度の2乗に比例して長くなる。', '["○（正しい）","×（誤り）"]', 1, 3, '停止距離のうち、制動距離は速度の2乗に比例しますが、空走距離は速度に比例するため、停止距離全体が2乗に比例するわけではありません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '夜間は視界が悪いため、昼間よりも停止距離を短く見積もって運転する必要がある。', '["○（正しい）","×（誤り）"]', 1, 2, '夜間は危険の発見が遅れがちになるため、より余裕を持った車間距離と速度で運転しなければなりません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', 'マイナ免許証を保有している場合、従来のプラスチック製免許証を携帯する必要は一切ない。', '["○（正しい）","×（誤り）"]', 1, 2, 'マイナ免許証のみ、従来免許証のみ、両方持ちの選択が可能です。マイナ免許証のみを選択した場合は不要ですが、携帯義務の有無は自身の選択によります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '雪道ではタイヤと路面の摩擦が極端に小さくなるため、制動距離は非常に長くなる。', '["○（正しい）","×（誤り）"]', 0, 1, '雪道や凍結路面は摩擦係数が低く、制動距離が著しく伸びるため、極めて慎重な運転が必要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '前車が急ブレーキをかけた際、追突を避けるためには、車間距離を確保しているだけでは不十分で、常に前方の交通状況を注視する必要がある。', '["○（正しい）","×（誤り）"]', 0, 1, '車間距離の確保は基本ですが、前方の状況を予測し、危険を早期に察知することが事故防止の要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '生活道路（中央線なし）において、歩行者が横断しようとしている場合、時速30キロメートル以下であれば減速せずに通過してもよい。', '["○（正しい）","×（誤り）"]', 1, 1, '歩行者が横断しようとしている時は、一時停止して歩行者の通行を妨げないようにしなければなりません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '下り坂では、上り坂に比べて制動距離が長くなる傾向がある。', '["○（正しい）","×（誤り）"]', 0, 2, '下り坂は重力が加速に働くため、ブレーキの負担が増し、制動距離が長くなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '自転車の交通違反に対する青切符制度は、16歳以上の自転車運転者が対象である。', '["○（正しい）","×（誤り）"]', 0, 2, '2026年4月施行の改正法により、16歳以上の自転車運転者に対して青切符制度が導入されました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '時速60キロメートルで走行しているとき、空走距離は概ね10メートル程度である。', '["○（正しい）","×（誤り）"]', 0, 3, '空走時間は一般的に約1秒とされており、時速60km（約16.7m/秒）であれば、空走距離は約17m前後となります。問題文の「10メートル程度」は概算として許容範囲です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '道路標識で時速40キロメートルと指定されている道路では、中央線があっても時速40キロメートルが最高速度である。', '["○（正しい）","×（誤り）"]', 0, 1, '法定速度よりも標識による指定速度が優先されます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '大型貨物自動車の法定最高速度は、普通自動車と同じである。', '["○（正しい）","×（誤り）"]', 1, 2, '大型貨物自動車など、車種によって法定最高速度が異なる場合があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '追い越しをする際は、加速して短時間で追い越しを完了させるのが安全である。', '["○（正しい）","×（誤り）"]', 0, 1, '追い越しは対向車線にはみ出す危険な行為であるため、速やかに完了させることが原則です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '仮免許練習標識は、自動車の前面と後面にのみ表示すればよい。', '["○（正しい）","×（誤り）"]', 0, 1, '仮免許練習標識は、地上0.4m以上1.2m以下の位置に、前後両方に表示する義務があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '中央線が黄色い実線であっても、工事車両を避けるためであれば、はみ出して追い越すことができる。', '["○（正しい）","×（誤り）"]', 1, 2, '黄色い実線は「追い越しのためのはみ出し」が禁止です。工事車両などの障害物を避けるためのやむを得ないはみ出しは可能ですが、追い越しは不可です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '運転免許証の更新は、マイナ免許証を選択していても、更新講習を受ける必要がある。', '["○（正しい）","×（誤り）"]', 0, 1, '免許証の形式に関わらず、安全運転のための更新講習は義務付けられています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '制動距離は、タイヤの摩耗状態によって変化する。', '["○（正しい）","×（誤り）"]', 0, 1, 'タイヤが摩耗すると路面とのグリップ力が低下し、制動距離が長くなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '生活道路において、時速30キロメートルを超えて走行することは、いかなる場合も認められない。', '["○（正しい）","×（誤り）"]', 1, 2, '緊急自動車がサイレンを鳴らして走行している場合など、例外的に法定速度を超えることが認められるケースがあります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '前の車が原動機付自転車を追い越そうとしているとき、その追い越しを妨げなければ、自分も続けて追い越してもよい。', '["○（正しい）","×（誤り）"]', 1, 2, '二重追い越しは禁止されています。前の車が追い越しを始めたら、その追い越しが終わるまで待たなければなりません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '道路の曲がり角付近では、前の車が低速で走っていても追い越してはならない。', '["○（正しい）","×（誤り）"]', 0, 1, '道路の曲がり角付近は追い越し禁止場所です。前車が低速であっても追い越しは認められません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '自転車を追い越すときは、安全な間隔をあけるか、あるいは徐行しなければならない。', '["○（正しい）","×（誤り）"]', 0, 2, '自転車との側方間隔が確保できない場合は、安全な速度まで減速するか徐行して追い越す義務があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '横断歩道に近づいたとき、前車が停止していなければ、横断歩道の手前であっても追い越すことができる。', '["○（正しい）","×（誤り）"]', 1, 2, '横断歩道や自転車横断帯とその手前30メートル以内は、追い越し・追い抜きが禁止されています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '追い越しをするときは、右側から追い越すのが原則であるが、前車が右折のため中央に寄っている場合は左側から追い越すことができる。', '["○（正しい）","×（誤り）"]', 0, 2, '前車が右折のため中央に寄っている場合、左側を通行して追い抜くことは例外的に認められています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '踏切とその手前30メートル以内は、追い越しが禁止されているが、追い抜きは禁止されていない。', '["○（正しい）","×（誤り）"]', 1, 2, '踏切とその手前30メートル以内は、追い越しだけでなく追い抜きも禁止されています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '追い越しをするときは、前車の右側を通行し、追い越しが終わるまで十分な距離を保って戻らなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '追い越しは右側から行い、前車の進路を妨げないよう十分な距離をとって戻るのが基本ルールです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '坂の頂上付近は、追い越し禁止場所であるが、追い抜きは禁止されていない。', '["○（正しい）","×（誤り）"]', 1, 2, '坂の頂上付近は追い越し禁止場所です。追い越しとは進路を変えて前車の側方を通過することであり、追い抜きも同様に禁止です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '追い越しをしようとする車が、自分の後ろから追い越しを始めたときは、速度を上げて追い越しを妨げてはならない。', '["○（正しい）","×（誤り）"]', 0, 1, '追い越される側は、速度を上げたり進路を塞いだりして、追い越しを妨害してはならない義務があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '交差点の中やその手前30メートル以内は、追い越し禁止場所である。', '["○（正しい）","×（誤り）"]', 0, 1, '交差点およびその手前30メートル以内は、追い越し禁止場所です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '追い越しをするときは、必ず方向指示器を出して合図をしなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '追い越しのために進路を変える際は、必ず右方向指示器で合図を出す必要があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', 'トンネル内は、車両通行帯がある場合でも追い越しが禁止されている。', '["○（正しい）","×（誤り）"]', 1, 2, 'トンネル内であっても、車両通行帯がある道路では追い越しが可能です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '自転車を追い越す際、十分な側方間隔がとれないときは、安全な速度まで落として進行しなければならない。', '["○（正しい）","×（誤り）"]', 0, 2, '自転車の安全確保のため、側方間隔が不十分な場合は徐行や減速が義務付けられています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '追い越し禁止の標識がある場所でも、原動機付自転車であれば追い越してもよい。', '["○（正しい）","×（誤り）"]', 1, 1, '追い越し禁止の標識がある場所では、相手が原付であっても追い越しは禁止です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '前の車が追い越しをしようとしているとき、自分も続いて追い越すことを「二重追い越し」といい、禁止されている。', '["○（正しい）","×（誤り）"]', 0, 1, '二重追い越しは大変危険であり、道路交通法で禁止されています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '追い越しが終わった後、すぐに元の通行帯に戻るために急ハンドルを切って前車の直前に入った。', '["○（正しい）","×（誤り）"]', 1, 2, '追い越し後は、前車の進路を妨げないよう十分な距離をとってから戻る必要があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '信号機のある交差点では、追い越しが禁止されている。', '["○（正しい）","×（誤り）"]', 1, 2, '信号機のある交差点で、優先道路を通行している場合などは追い越しが禁止されていません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '追い越しをしようとするとき、前車が右折の合図を出していたら、追い越してはならない。', '["○（正しい）","×（誤り）"]', 0, 2, '前車が右折しようとしているときに追い越すと、衝突の危険があるため禁止されています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '追い越し禁止場所であっても、停止している車を避けるために右側を通行することは追い越しには当たらない。', '["○（正しい）","×（誤り）"]', 0, 2, '停止している車を避ける行為は「追い越し」ではなく「追い抜き」や「回避」であり、追い越し禁止場所でも可能です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '中央線が黄色の実線である道路では、追い越しのためにその線をはみ出してはならない。', '["○（正しい）","×（誤り）"]', 0, 1, '黄色い実線の中央線は、追い越しのためにはみ出すことが禁止されています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '自転車を追い越す際、警音器を鳴らして注意を促せば、側方間隔が狭くても追い越してよい。', '["○（正しい）","×（誤り）"]', 1, 2, '警音器の使用は危険を避ける場合に限られます。側方間隔が狭い場合は、鳴らすのではなく減速して安全を確保すべきです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '追い越しをするときは、前車の速度や道路状況をよく確認し、安全かつ迅速に行わなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '追い越しは危険を伴うため、状況判断と迅速な操作が求められます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '追い越し禁止場所で、自転車を追い越すことは可能である。', '["○（正しい）","×（誤り）"]', 1, 2, '追い越し禁止場所では、相手が自転車であっても追い越しは禁止です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '追い越しを終えて元の通行帯に戻るときは、左方向指示器を出して合図をする。', '["○（正しい）","×（誤り）"]', 0, 1, '進路を左に戻す際は、左方向指示器で合図を出すのがルールです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '追い越しをしようとする車がある場合、追い越される車は、できるだけ左に寄って進路を譲らなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '追い越される車は、追い越しを妨げないよう左側に寄る義務があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '車両通行帯のない道路では、追い越しのために中央線をはみ出してもよい場所がある。', '["○（正しい）","×（誤り）"]', 0, 2, '追い越し禁止の標識や黄色い実線がない場所であれば、中央線をはみ出して追い越すことができます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '追い越し禁止場所で、路肩を通行して前車を追い抜くことは認められている。', '["○（正しい）","×（誤り）"]', 1, 2, '路肩を通行しての追い抜きは禁止されています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '追い越しをするときは、前車の右側を通行するのが原則である。', '["○（正しい）","×（誤り）"]', 0, 1, '追い越しは右側から行うのが道路交通法の原則です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '追い越し禁止場所において、故障車を追い越すことは禁止されている。', '["○（正しい）","×（誤り）"]', 1, 2, '故障車などの停止車両を避ける行為は、追い越し禁止場所であっても可能です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '自転車を追い越す際の側方間隔は、1.5メートル以上あけなければならないという規定がある。', '["○（正しい）","×（誤り）"]', 1, 2, '具体的な数値規定はありませんが、安全な間隔をあけるか、それができない場合は徐行する義務があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '停車とは、車両等が客の乗り降りのため、または荷物の積み降ろしのため、短時間停止することや、運転者が車両から離れないで直ちに運転できる状態での停止をいう。', '["○（正しい）","×（誤り）"]', 0, 1, '停車の定義は、客待ちや荷待ち、故障などの理由で短時間停止することや、運転者がすぐに動かせる状態での停止を指します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '駐車とは、車両等が客の乗り降りのため、または荷物の積み降ろしのため、短時間停止することをいう。', '["○（正しい）","×（誤り）"]', 1, 1, '設問の内容は「停車」の定義です。「駐車」は、継続的な停止や運転者が離れていてすぐに動かせない状態などを指します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '交差点から5メートル以内の場所は、駐車も停車も禁止されている。', '["○（正しい）","×（誤り）"]', 0, 1, '交差点およびその側端から5メートル以内の場所は、駐停車禁止場所です。交通の妨げになるため厳しく制限されています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '横断歩道や自転車横断帯の前後5メートル以内の場所は、駐車および停車が禁止されている。', '["○（正しい）","×（誤り）"]', 0, 1, '横断歩道等の周辺は歩行者や自転車の視界を遮るため、前後5メートル以内は駐停車禁止です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', 'バス停留所の標示板から10メートル以内の場所は、運行時間中に限り駐車が禁止される。', '["○（正しい）","×（誤り）"]', 0, 2, 'バス停留所の標示板から10メートル以内は駐車禁止です。ただし、停車は禁止されていません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '駐車禁止の標識がある場所であっても、荷物の積み降ろしのために短時間停止する場合は駐車にならないので禁止されない。', '["○（正しい）","×（誤り）"]', 1, 2, '荷物の積み降ろしであっても、運転者が車両から離れる場合や、一定時間を超える場合は「駐車」とみなされ禁止されます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '道路の左側に沿って駐車する場合、車両の右側に3.5メートル以上の余地がなければならない。', '["○（正しい）","×（誤り）"]', 0, 2, '駐車禁止場所でなくても、右側に3.5メートル以上の余地がない場所に駐車することは禁止されています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '消火栓や指定消防水利の標識から5メートル以内の場所は、駐車は禁止されているが、停車は禁止されていない。', '["○（正しい）","×（誤り）"]', 0, 2, '消防用施設付近は駐車禁止ですが、停車は禁止されていません。ただし、火災報知器から1メートル以内は駐停車禁止です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '時間制限駐車区間において、パーキング・メーターが作動していない時間は、駐車してもよい。', '["○（正しい）","×（誤り）"]', 1, 2, '時間制限駐車区間では、指定された時間内であればパーキング・メーター等を利用して駐車できますが、それ以外は標識に従う必要があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '坂の頂上付近や勾配の急な坂は、駐停車禁止場所である。', '["○（正しい）","×（誤り）"]', 0, 1, '見通しが悪く危険なため、坂の頂上付近や勾配の急な坂は駐停車禁止場所と定められています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', 'トンネル内は、駐停車禁止場所である。', '["○（正しい）","×（誤り）"]', 0, 1, 'トンネル内は視界が悪く危険なため、駐停車禁止です。ただし、駐車禁止の標識がある場合を除きます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '踏切から10メートル以内の場所は、駐停車禁止である。', '["○（正しい）","×（誤り）"]', 0, 1, '踏切内での事故防止のため、踏切の前後10メートル以内は駐停車禁止とされています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '駐車禁止の標識がある場所で、運転者が車内にいれば駐車してもよい。', '["○（正しい）","×（誤り）"]', 1, 1, '駐車禁止場所では、運転者が車内にいても駐車は禁止です。停車は可能な場合があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '車両は、道路の左側に沿って、他の交通の妨げにならないように駐車しなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '駐車の基本ルールです。左側に沿い、かつ他の交通の妨げにならない場所を選ぶ必要があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '歩道や路側帯がある道路では、歩道や路側帯に乗り上げて駐車しなければならない。', '["○（正しい）","×（誤り）"]', 1, 2, '歩道や路側帯は歩行者のための場所です。駐車のために乗り上げることは禁止されています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '駐車するときは、エンジンを止め、ブレーキをかけ、盗難防止措置をとらなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '駐車時の基本的な安全措置です。エンジン停止、パーキングブレーキ、施錠は必須です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '放置車両とは、運転者が車両を離れて直ちに運転できない状態にある車両をいう。', '["○（正しい）","×（誤り）"]', 0, 2, '運転者が車両を離れ、ただちに運転できない状態は「放置駐車」とみなされ、厳しい処罰の対象となります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '駐車禁止の場所であっても、警察署長の許可を受けた場合は駐車できる。', '["○（正しい）","×（誤り）"]', 0, 2, '工事や引越しなど、やむを得ない事情で警察署長の許可を受けた場合は、駐車禁止場所でも駐車が認められます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '路側帯が設置されている道路で、路側帯の幅が0.75メートル以下の場合は、その中に駐車してもよい。', '["○（正しい）","×（誤り）"]', 1, 3, '路側帯に駐車する場合、歩行者の通行のために0.75メートルの余地が必要です。路側帯が狭い場合は駐車できません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '交差点の側端から5メートル以内の場所は駐停車禁止だが、信号機がある交差点であれば駐車してもよい。', '["○（正しい）","×（誤り）"]', 1, 2, '信号機の有無にかかわらず、交差点から5メートル以内は駐停車禁止です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '横断歩道から10メートル以内の場所は、駐停車禁止である。', '["○（正しい）","×（誤り）"]', 1, 2, '横断歩道の駐停車禁止範囲は「前後5メートル以内」です。10メートルではありません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '駐車禁止の標識がある場所で、短時間の荷物の積み降ろしであれば、運転者がすぐ戻れる状態でも禁止される。', '["○（正しい）","×（誤り）"]', 0, 2, '駐車禁止の場所では、たとえ短時間であっても「駐車」に該当する行為は禁止されます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '時間制限駐車区間では、パーキング・チケットを発給する装置がある場合、チケットを車内の見やすい場所に掲示しなければならない。', '["○（正しい）","×（誤り）"]', 0, 2, 'パーキング・チケット方式の場所では、チケットを正しく掲示することが義務付けられています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '駐車するときは、道路の左側に沿って、他の車両の通行の妨げにならないようにしなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '道路交通法で定められた基本的な駐車方法です。左側に沿うことが原則です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '消火栓から5メートル以内の場所は、停車も禁止されている。', '["○（正しい）","×（誤り）"]', 1, 2, '消火栓付近は駐車禁止ですが、停車は禁止されていません。ひっかけ問題の定番です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '駐停車禁止の場所であっても、故障などでやむを得ず停止する場合は禁止されない。', '["○（正しい）","×（誤り）"]', 0, 2, '故障など、やむを得ない事情による停止は、駐停車禁止場所であっても違反にはなりません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '駐車禁止の場所で、運転者が車内にいて、すぐに移動できる状態であれば駐車してもよい。', '["○（正しい）","×（誤り）"]', 1, 2, '駐車禁止場所では、運転者の有無や移動の可否にかかわらず駐車は禁止です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '道路の曲がり角から5メートル以内の場所は、駐停車禁止である。', '["○（正しい）","×（誤り）"]', 0, 1, '見通しが悪く危険なため、道路の曲がり角から5メートル以内は駐停車禁止です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '駐車禁止の標識がある場所で、人の乗り降りのために停止することは「駐車」にあたる。', '["○（正しい）","×（誤り）"]', 1, 2, '人の乗り降りのための短時間停止は「停車」であり、駐車禁止場所でも可能です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '安全地帯の左側とその前後10メートル以内の場所は、駐停車禁止である。', '["○（正しい）","×（誤り）"]', 0, 2, '安全地帯は歩行者の避難場所であるため、その周辺は駐停車禁止と定められています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '右折や左折、または進路を変更しようとするときは、その行為をしようとする地点の30メートル手前の地点に達したときに合図を行わなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '道路交通法で定められた合図の時期です。30メートル手前で合図を出し、動作が終わるまで継続する必要があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '警音器（クラクション）は、道路標識などで指定された場所のほか、見通しのきかない交差点や曲がり角を通行するときにも鳴らさなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '警音器の使用は、標識がある場所のほか、見通しのきかない交差点、曲がり角、上り坂の頂上付近で義務付けられています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '普通自動車の乗車定員は、運転者を含めて10人以下である。', '["○（正しい）","×（誤り）"]', 0, 1, '普通自動車の定義は、乗車定員10人以下、車両総重量3.5トン未満、最大積載量2トン未満の自動車を指します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '警音器は、危険を避けるためにやむを得ない場合であれば、どこでも鳴らすことができる。', '["○（正しい）","×（誤り）"]', 0, 2, '警音器は原則として使用制限がありますが、危険を避けるためにやむを得ない場合は、場所を問わず使用することが認められています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '普通自動車の荷台には、原則として荷物を積むことはできないが、警察署長の許可を得れば人を乗せることができる。', '["○（正しい）","×（誤り）"]', 1, 2, '荷台への人の乗車は原則禁止です。警察署長の許可を得ても、荷台に人を乗せての走行は認められません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '徐行場所や停止場所で合図を出すときは、その行為をしようとする地点の30メートル手前で行う。', '["○（正しい）","×（誤り）"]', 1, 2, '徐行・停止・後退の合図は、その行為をしようとするとき（直前）に行うのがルールです。30メートル手前ではありません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '普通自動車の積載物の長さは、自動車の長さの1.2倍までなら許可なしで積むことができる。', '["○（正しい）","×（誤り）"]', 1, 2, '積載物の長さは自動車の長さの1.1倍までです。1.2倍は違反になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '合図は、進路変更が完了するまで継続し、変更が終わったら速やかにやめなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '合図は進路変更などの行為が完了するまで継続し、完了後は速やかにやめるのが正しい手順です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '警音器は、前方の車がなかなか発進しないときに、注意を促す目的であれば鳴らしてもよい。', '["○（正しい）","×（誤り）"]', 1, 2, '警音器は危険防止のためにやむを得ない場合以外、使用してはいけません。催促のための使用は違反です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '積載物の高さは、地面から3.8メートルまで積むことができる。', '["○（正しい）","×（誤り）"]', 0, 2, '普通自動車の積載物の高さ制限は、地面から3.8メートル以下です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '追い越しをするときは、追い越しを始めようとする地点の30メートル手前で合図を出す。', '["○（正しい）","×（誤り）"]', 1, 2, '追い越しの合図は、追い越しを始めようとする時（直前）に行います。30メートル手前ではありません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '乗車定員が5人の普通自動車に、12歳未満の子供を3人乗せる場合、大人2人分として計算することができる。', '["○（正しい）","×（誤り）"]', 0, 2, '12歳未満の子供は3人で大人2人分として計算できます。この場合、定員5人に対し大人3人＋子供3人＝定員内となります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '警音器を鳴らさなければならない場所であっても、周囲に人がいないことが明らかな場合は鳴らさなくてもよい。', '["○（正しい）","×（誤り）"]', 1, 2, '警音器の使用義務がある場所（見通しのきかない交差点等）では、周囲の状況に関わらず必ず鳴らさなければなりません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '自動車の積載物の幅は、自動車の幅の1.2倍まで積むことができる。', '["○（正しい）","×（誤り）"]', 1, 2, '積載物の幅は自動車の幅までです。1.2倍は認められていません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '進路変更の合図は、変更しようとする3秒前に行う。', '["○（正しい）","×（誤り）"]', 1, 2, '進路変更の合図は、変更しようとする3秒前ではなく、30メートル手前で行います。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '普通自動車の積載物は、自動車の車体の前後から、それぞれ車体の長さの10分の1までならはみ出して積むことができる。', '["○（正しい）","×（誤り）"]', 0, 2, '積載物は車体の長さの10分の1までなら、前後にはみ出して積むことが可能です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '警音器は、危険を避けるためであっても、深夜の住宅街では鳴らしてはならない。', '["○（正しい）","×（誤り）"]', 1, 2, '危険を避けるためにやむを得ない場合は、場所や時間を問わず警音器を使用しなければなりません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '合図は、周囲の交通に自分の意思を伝えるためのものなので、誰もいない道路では出す必要はない。', '["○（正しい）","×（誤り）"]', 1, 2, '合図は周囲の交通の有無に関わらず、法令で定められた場所・時期に必ず行わなければなりません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '乗車定員が5人の普通自動車に、運転者を含めて6人乗ることは、全員がシートベルトを着用していれば認められる。', '["○（正しい）","×（誤り）"]', 1, 1, 'シートベルトの有無に関わらず、乗車定員を超えて乗車することは違反です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '合図の時期は、右左折や進路変更の30メートル手前だが、転回（Uターン）の場合はその地点の30メートル手前でよい。', '["○（正しい）","×（誤り）"]', 0, 2, '転回（Uターン）も右折と同様に、その地点の30メートル手前で合図を行う必要があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '積載物の重量は、自動車の最大積載量を超えて積んではならない。', '["○（正しい）","×（誤り）"]', 0, 1, '積載物の重量は、自動車検査証に記載された最大積載量を超えてはいけません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '警音器は、歩行者に道を譲ってもらったときのお礼として鳴らすことができる。', '["○（正しい）","×（誤り）"]', 1, 1, '警音器はお礼や挨拶のために使用してはいけません。危険防止の目的以外での使用は禁止です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '普通自動車で荷物を積む際、荷物の高さが制限を超えてしまう場合は、警察署長の許可を得れば積むことができる。', '["○（正しい）","×（誤り）"]', 0, 2, '制限を超える積載物であっても、出発地の警察署長の許可を得れば積載して通行することが可能です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '前方の車が右折しようとしているとき、その車の右側を通行して追い越すことは禁止されている。', '["○（正しい）","×（誤り）"]', 0, 2, '右折しようとしている車の右側を通行して追い越すことは、道路交通法で禁止されています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '合図は、手または方向指示器によって行うが、夜間は必ず方向指示器を使用しなければならない。', '["○（正しい）","×（誤り）"]', 0, 2, '夜間は手による合図では周囲から見えにくいため、方向指示器を使用することが義務付けられています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '乗車定員は、運転者を含めた人数であり、12歳未満の子供は3人で大人2人分として計算できる。', '["○（正しい）","×（誤り）"]', 0, 1, '乗車定員は運転者を含みます。また、子供の計算方法もこの通りです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '警音器は、見通しのきかない交差点で、一時停止の標識がある場合は鳴らさなくてもよい。', '["○（正しい）","×（誤り）"]', 1, 2, '一時停止の有無に関わらず、見通しのきかない交差点では警音器を鳴らす義務があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '積載物の長さは、自動車の長さの1.1倍までなら許可なしで積むことができる。', '["○（正しい）","×（誤り）"]', 0, 2, '積載物の長さは自動車の長さの1.1倍までが制限内です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '合図は、進路変更の直前に行えばよい。', '["○（正しい）","×（誤り）"]', 1, 1, '進路変更の合図は、30メートル手前で行うのがルールです。直前では遅すぎます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '普通自動車の荷台に荷物を積む場合、荷物が荷台から少しでもはみ出していれば、必ず警察署長の許可が必要である。', '["○（正しい）","×（誤り）"]', 1, 2, '一定の範囲内（長さの1.1倍、幅、高さの制限内）であれば、許可なしで積載可能です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '17歳6か月に達した者は、仮免許を取得して路上練習を行うことができる。', '["○（正しい）","×（誤り）"]', 0, 1, '2026年4月施行の改正により、仮免許および本免許の受験資格は17歳6か月に引き下げられました。ただし、免許証の交付は18歳からです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '中央線や車両通行帯のない生活道路では、法定最高速度は時速30kmである。', '["○（正しい）","×（誤り）"]', 0, 1, '2026年9月施行の改正により、中央線や車両通行帯のない一般道路の法定最高速度は時速30kmに制限されました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '緊急自動車が近づいてきたときは、交差点付近でなければ、道路の左側に寄って一時停止しなければならない。', '["○（正しい）","×（誤り）"]', 1, 2, '緊急自動車に道を譲る際は、左側に寄るだけでよく、一時停止の義務はありません。交差点付近では左側に寄って停止します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '初心運転者標識（若葉マーク）は、普通免許を取得して1年未満の人が運転する際に、車の前後の見やすい位置に表示しなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '初心運転者標識は、免許取得後1年未満のドライバーが義務付けられている表示です。前後両方に表示が必要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '仮免許練習中の車を運転するときは、指導員が助手席に乗っていれば、仮免許証を携帯していなくてもよい。', '["○（正しい）","×（誤り）"]', 1, 2, '仮免許練習中であっても、運転者は必ず仮免許証を携帯しなければなりません。携帯義務は免除されません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '仮免許で路上練習をする際は、車体の前後に「仮免許練習中」の標識を付けなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '仮免許練習中の標識は、前後の見やすい位置に表示することが法令で義務付けられています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', 'マイナ免許証を保有している場合、従来のプラスチック製免許証を所持する必要は一切ない。', '["○（正しい）","×（誤り）"]', 1, 2, 'マイナ免許証、従来免許証、両方持ちのいずれかを選択可能です。必ずしも従来免許証が不要になるわけではありません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '緊急自動車が近づいてきたとき、交差点内であれば、交差点を避けて左側に寄って停止しなければならない。', '["○（正しい）","×（誤り）"]', 0, 2, '交差点内では、交差点を避けて左側に寄って停止するのが正しい対応です。交差点内に留まるのは危険です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '仮免許の練習に同乗できるのは、指定自動車教習所の指導員のみである。', '["○（正しい）","×（誤り）"]', 1, 2, '指導員だけでなく、当該免許を3年以上受けている者や、公安委員会の指定を受けた者なども同乗可能です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '中央線のある一般道路の法定最高速度は、標識等で指定がない限り時速60kmである。', '["○（正しい）","×（誤り）"]', 0, 1, '2026年9月の改正でも、中央線等がある一般道路の法定最高速度は時速60kmのまま維持されています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '初心運転者標識を付けている車を幅寄せしたり、無理な割り込みをしたりすることは禁止されている。', '["○（正しい）","×（誤り）"]', 0, 1, '初心運転者保護義務により、周囲のドライバーは幅寄せや割り込みをしてはなりません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '仮免許で運転できるのは、練習のために指導者が同乗している場合に限られる。', '["○（正しい）","×（誤り）"]', 0, 1, '仮免許はあくまで練習用です。指導者が同乗し、かつ練習目的である必要があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '自転車の交通違反に対する青切符制度は、16歳未満の者にも適用される。', '["○（正しい）","×（誤り）"]', 1, 2, '2026年4月施行の自転車青切符制度は、16歳以上の者が対象です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '緊急自動車が近づいてきたとき、一方通行の道路では、右側に寄って停止してもよい。', '["○（正しい）","×（誤り）"]', 1, 2, '一方通行であっても、緊急自動車に対しては左側に寄って道を譲るのが原則です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '仮免許証の有効期限は、交付の日から6か月である。', '["○（正しい）","×（誤り）"]', 0, 1, '仮免許証の有効期間は、交付から6か月と定められています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '17歳6か月に達していれば、仮免許証を持っていなくても路上で練習できる。', '["○（正しい）","×（誤り）"]', 1, 1, '年齢要件を満たしていても、仮免許証を取得していなければ路上での練習はできません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '初心運転者標識を付けている車が、交通の混雑などでやむを得ず幅寄せされた場合、相手を罰することはできない。', '["○（正しい）","×（誤り）"]', 1, 2, '交通の混雑に関わらず、初心運転者に対する幅寄せや割り込みは禁止されており、違反すれば罰則の対象となります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '緊急自動車が近づいてきたとき、道路の左側に寄ることができない場合は、道路の右側に寄って停止してもよい。', '["○（正しい）","×（誤り）"]', 1, 2, '左側に寄ることができない場合は、左側に寄って停止するだけでよく、右側に寄ることは認められていません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '仮免許練習中の標識は、マグネット式などで簡単に取り外しができるものでもよい。', '["○（正しい）","×（誤り）"]', 0, 1, '標識の材質に規定はありませんが、前後の見やすい位置に確実に表示されている必要があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '自転車の追い越し時に、十分な側方間隔が取れない場合は、徐行して追い越さなければならない。', '["○（正しい）","×（誤り）"]', 0, 2, '側方間隔が取れない場合は、安全な速度（徐行など）で通過することが求められます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '仮免許で高速道路を走行することは、指導員が同乗していれば認められている。', '["○（正しい）","×（誤り）"]', 1, 2, '仮免許での高速道路および自動車専用道路の走行は禁止されています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', 'マイナ免許証を紛失した場合、速やかに警察署等へ届け出る必要がある。', '["○（正しい）","×（誤り）"]', 0, 1, '免許証（マイナ免許証含む）の紛失は、悪用を防ぐため速やかな届け出が義務です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '初心運転者標識は、免許取得後1年を経過した後は、外してもよい。', '["○（正しい）","×（誤り）"]', 0, 1, '初心運転者標識の表示義務は1年です。1年経過後は外すことができます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '緊急自動車が近づいてきたとき、交差点では直ちに停止しなければならない。', '["○（正しい）","×（誤り）"]', 1, 2, '交差点では、交差点を避けて左側に寄って停止します。交差点内で停止してはなりません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '仮免許の練習中に事故を起こした場合、指導員は責任を負わない。', '["○（正しい）","×（誤り）"]', 1, 2, '仮免許練習中の事故については、指導員も監督責任を問われる可能性があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '生活道路（中央線なし）での法定速度は時速30kmだが、標識で40kmとあればそれに従う。', '["○（正しい）","×（誤り）"]', 0, 1, '法定速度は標識等による指定がない場合の基準であり、標識がある場合は標識の速度が優先されます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '自転車の青切符制度は、すべての自転車利用者が対象である。', '["○（正しい）","×（誤り）"]', 1, 2, '青切符制度は16歳以上の自転車利用者が対象です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '仮免許証を忘れて路上練習をした場合、無免許運転にはならない。', '["○（正しい）","×（誤り）"]', 1, 2, '仮免許証を携帯していない状態での運転は、無免許運転とみなされる可能性があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_karimen', '初心運転者標識は、車の後ろ側だけに付けていればよい。', '["○（正しい）","×（誤り）"]', 1, 1, '初心運転者標識は、前後の見やすい位置に両方表示しなければなりません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '高速自動車国道の本線車道における法定最高速度は、標識や標示による指定がない場合、普通乗用自動車は時速100キロメートルである。', '["○（正しい）","×（誤り）"]', 0, 1, '高速自動車国道の本線車道では、指定がない場合、普通乗用自動車の法定最高速度は100km/hと定められています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '高速道路で故障によりやむを得ず路肩に停車する場合、停止表示器材を車の後方に設置する義務がある。', '["○（正しい）","×（誤り）"]', 0, 2, '高速道路上で故障等で停止する場合、停止表示器材（三角表示板や停止表示灯）を車の後方に設置し、後続車に危険を知らせる義務があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '高速道路の本線車道に合流する場合、加速車線を使って十分に加速し、本線車道を走行する車の通行を妨げないようにしなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '合流時は本線車道の交通を優先し、加速車線で速度を合わせてスムーズに合流することが求められます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '高速道路の追越車線は、追い越しをするための車線であるため、追い越しが終わった後もそのまま走行し続けてよい。', '["○（正しい）","×（誤り）"]', 1, 1, '追越車線は追い越しのために設けられた車線です。追い越しが終わったら速やかに左側の走行車線に戻らなければなりません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '高速自動車国道の最低速度は、標識や標示による指定がない場合、時速50キロメートルである。', '["○（正しい）","×（誤り）"]', 0, 2, '高速自動車国道の本線車道では、指定がない限り最低速度は50km/hです。これより遅い速度で走ることは禁止されています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '高速道路で渋滞の最後尾に並ぶ際は、ハザードランプを点灯させて後続車に合図を送るのが望ましい。', '["○（正しい）","×（誤り）"]', 0, 1, '追突事故防止のため、渋滞の最後尾ではハザードランプを点灯させ、後続車に注意を促すことが推奨されます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '高速道路において、故障車を路肩に移動させることが困難な場合、運転者は速やかに車から降りて、ガードレールの外側などの安全な場所に避難しなければならない。', '["○（正しい）","×（誤り）"]', 0, 2, '高速道路上での人身事故を防ぐため、車内に留まるのは危険です。速やかに安全な場所へ避難し、110番や道路緊急ダイヤルへ通報してください。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '高速道路において、追い越しをする際は、必ず右側の車線を通行しなければならない。', '["○（正しい）","×（誤り）"]', 0, 2, '追い越しは原則として右側の車線から行います。左側からの追い越し（追い抜き）は禁止されています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '高速道路では、いかなる理由があっても駐停車してはならない。', '["○（正しい）","×（誤り）"]', 1, 2, '故障や事故などのやむを得ない場合や、サービスエリア・パーキングエリアなど、法令で認められた場所では駐停車が可能です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '高速道路で走行中にタイヤがパンクしたときは、急ブレーキをかけてすぐに停止しなければならない。', '["○（正しい）","×（誤り）"]', 1, 2, '高速走行中の急ブレーキはスピンや転覆の危険があります。ハンドルをしっかり握り、エンジンブレーキ等で徐々に減速して路肩へ寄せるのが正解です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '高速道路において、本線車道から出口に向かう際は、減速車線に入ってから速度を落とさなければならない。', '["○（正しい）","×（誤り）"]', 0, 2, '本線車道で減速すると追突の危険があります。必ず減速車線に入ってから速度を落とすのがルールです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '高速道路において、大型貨物自動車の法定最高速度は、普通乗用自動車と同じである。', '["○（正しい）","×（誤り）"]', 1, 2, '高速自動車国道では、大型貨物自動車などは車種によって最高速度が異なる場合があります（一般的には80km/h制限が多い）。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '高速道路で車が故障して路肩に止めた場合、運転者は車の中に残って救助を待つのが最も安全である。', '["○（正しい）","×（誤り）"]', 1, 1, '車内に留まると、後続車が追突してきた際に重大な被害を受ける恐れがあります。速やかにガードレールの外側へ避難してください。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '高速道路において、追い越し車線を走行中に後方から速い車が近づいてきた場合、直ちに左側の車線に戻らなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '追越車線を走り続けることは通行帯違反になります。後続車の有無にかかわらず、追い越し後は速やかに走行車線へ戻る必要があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '高速道路では、トンネル内であっても追い越しをすることができる。', '["○（正しい）","×（誤り）"]', 0, 2, '一般道路のトンネル内では追い越し禁止の場所もありますが、高速道路のトンネル内は追い越しが禁止されていません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '高速道路で走行中、前方の車との車間距離は、時速100キロメートルの場合は少なくとも100メートル以上空けるのが望ましい。', '["○（正しい）","×（誤り）"]', 0, 1, '高速走行時は「速度と同じ数字の距離（メートル）」を空けることが安全運転の目安とされています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '高速道路において、料金所を通過する際は、一時停止しなければならない。', '["○（正しい）","×（誤り）"]', 1, 1, 'ETCレーンや一般レーンであっても、料金所では徐行して通過します。一時停止の標識がない限り、停止義務はありません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '高速道路において、故障により停止表示器材を設置する際、運転者は車の前方に設置しなければならない。', '["○（正しい）","×（誤り）"]', 1, 2, '停止表示器材は、後続車に危険を知らせるために「車の後方」に設置しなければなりません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '高速道路において、本線車道に合流する車は、本線車道を走行する車よりも優先される。', '["○（正しい）","×（誤り）"]', 1, 1, '本線車道を走行する車が優先です。合流する車は本線車の通行を妨げないようにしなければなりません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '高速道路において、二輪車で二人乗りをする場合、運転者の年齢や免許取得期間の制限がある。', '["○（正しい）","×（誤り）"]', 0, 2, '高速道路での二人乗りは、年齢20歳以上かつ大型二輪または普通二輪免許を受けてから3年以上経過している必要があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '高速道路で走行中、眠気を感じた場合は、次のサービスエリアまで我慢して走行し続けるべきである。', '["○（正しい）","×（誤り）"]', 1, 1, '眠気を感じたままの運転は非常に危険です。最寄りのパーキングエリアやサービスエリアで休憩をとるのが正解です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '高速道路において、追い越し車線を走行中に渋滞が発生した場合、追越車線をそのまま走行し続けてもよい。', '["○（正しい）","×（誤り）"]', 1, 2, '渋滞中であっても、追い越しをしないのであれば追越車線を空けて走行車線を走るのが原則です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '高速道路において、緊急自動車が近づいてきたときは、左側に寄って進路を譲らなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '緊急自動車が近づいてきたら、左側に寄って一時停止または徐行し、進路を譲る義務があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '高速道路において、車を運転中に携帯電話を使用することは、ハンズフリーであっても禁止されている。', '["○（正しい）","×（誤り）"]', 1, 2, '携帯電話の保持や注視は禁止ですが、ハンズフリー装置等を使用しての通話は直ちに禁止されているわけではありません（ただし安全運転義務違反には注意）。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '高速道路において、車両通行帯が設けられている道路では、指定された通行帯を通行しなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '車両通行帯がある道路では、原則として左側の通行帯を通行しなければなりません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '高速道路で故障車を路肩に止めた際、車から離れるときは、必ずエンジンを切り、鍵をかけておく必要がある。', '["○（正しい）","×（誤り）"]', 0, 2, '盗難防止および安全のため、車を離れる際はエンジンを切り、施錠することが基本です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '高速道路において、追い越しをするときは、追い越される車の右側を通行しなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '追い越しは、前車の右側を通行して行うのが原則です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '高速道路において、本線車道から路肩に停車する場合、ハザードランプを点灯させて合図しなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '路肩に停車する際は、周囲に意思表示をするためハザードランプを点灯させる必要があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '高速道路において、大型自動二輪車であれば、排気量に関係なく二人乗りが可能である。', '["○（正しい）","×（誤り）"]', 1, 2, '二人乗りには排気量制限（51cc以上）に加え、運転者の年齢や免許保有期間の条件を満たす必要があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '高速道路において、追い越し車線を走行中、追い越しが終わったにもかかわらず、後ろから車が来ていないのであれば、そのまま走行し続けてもよい。', '["○（正しい）","×（誤り）"]', 1, 2, '後ろから車が来ていなくても、追い越しが終われば速やかに走行車線に戻らなければなりません。追越車線は走り続けるための車線ではありません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '夜間、対向車と行き違うときや、他の車の直後を走行するときは、前照灯を減光するか、下向きに切り替えなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '対向車や先行車の運転を妨げないための義務です。ハイビームのままだと相手が眩惑され、事故の原因となるため必ず下向きにする必要があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '夜間、街灯が少なく見通しの悪い道路を走行するときは、歩行者や障害物を早期に発見するため、原則として前照灯は上向き（ハイビーム）にする。', '["○（正しい）","×（誤り）"]', 0, 1, '夜間の基本はハイビームです。対向車がいない場合や先行車がいない場合は、視認性を高めるために上向きで走行するのが原則です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '雨の日は路面が滑りやすくなるため、晴天時よりも停止距離が長くなることを考慮し、車間距離を十分にとる必要がある。', '["○（正しい）","×（誤り）"]', 0, 1, '雨天時はタイヤと路面の摩擦係数が低下し、制動距離が伸びます。空走距離と制動距離を合わせた停止距離が長くなるため、車間距離を広げるのが安全です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '夜間、対向車のライトが眩しくて前方が見えにくいときは、視線を少し左前方に向けて、眩惑を避けるようにする。', '["○（正しい）","×（誤り）"]', 0, 2, '対向車のライトを直視すると目が眩んでしまうため、左側の路肩や白線に視線を移して、眩惑を防ぎつつ進行方向を確認するのが正しい対処法です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '霧が発生しているときは、視界が悪くなるため、前照灯を上向き（ハイビーム）にして遠くまで光を届かせるのがよい。', '["○（正しい）","×（誤り）"]', 1, 2, '霧のときはハイビームにすると光が霧に反射して乱反射し、かえって視界が悪くなります。下向き（ロービーム）またはフォグランプを使用するのが適切です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '蒸発現象とは、夜間に対向車のライトに照らされて、歩行者や障害物が見えなくなる現象のことである。', '["○（正しい）","×（誤り）"]', 0, 2, '蒸発現象は、対向車のライトの光が強すぎて、その周辺にある歩行者や自転車などが背景に溶け込んで見えなくなる現象を指します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '雪道で発進するときは、アクセルを強く踏み込んで勢いよく発進すると、タイヤが空転しにくくスムーズに加速できる。', '["○（正しい）","×（誤り）"]', 1, 1, '雪道で急加速するとタイヤが空転（スリップ）しやすくなります。発進時はゆっくりとアクセルを踏み込むのが鉄則です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '凍結した路面（アイスバーン）では、ブレーキを一度に強く踏み込むとタイヤがロックしてスリップするため、数回に分けて踏むのがよい。', '["○（正しい）","×（誤り）"]', 0, 2, '凍結路面での急ブレーキは非常に危険です。ポンピングブレーキ（数回に分けて踏む）を行うことで、タイヤのロックを防ぎ制動を安定させます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '夜間、道路に駐車や停車をする場合は、他の交通に自分の車の存在を知らせるため、前照灯をつけたままにしなければならない。', '["○（正しい）","×（誤り）"]', 1, 2, '夜間、道路上に駐車・停車する場合は、前照灯ではなく、尾灯（テールランプ）や車幅灯を点灯させなければなりません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '雨の日に高速道路を走行中、タイヤと路面の間に水膜ができる「ハイドロプレーニング現象」が発生すると、ハンドルやブレーキが効かなくなる。', '["○（正しい）","×（誤り）"]', 0, 2, 'ハイドロプレーニング現象は、タイヤが路面から浮き上がり、コントロール不能になる現象です。速度を落として走行することが重要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '夜間、街灯が十分にある明るい道路であれば、前照灯を消して走行してもよい。', '["○（正しい）","×（誤り）"]', 1, 1, '夜間はたとえ街灯があっても、自分の存在を周囲に知らせるため、必ず前照灯を点灯しなければなりません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '雪道で下り坂を走行するときは、フットブレーキを多用するとスリップしやすいため、エンジンブレーキを併用して速度を抑える。', '["○（正しい）","×（誤り）"]', 0, 1, '雪道でのフットブレーキはスリップの元です。エンジンブレーキを積極的に活用し、速度を低く保つのが安全運転の基本です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '雨の日は、歩行者に泥水をはねかける恐れがあるため、水たまりがある場所では徐行や一時停止をして歩行者に配慮しなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '道路交通法上の義務であり、歩行者への思いやりとしても必須です。泥水をはねて汚すことはマナー違反かつ違反行為です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '夜間、追い越しをするときは、前方の車に合図を送るために、一時的にハイビームにしてから追い越すのが望ましい。', '["○（正しい）","×（誤り）"]', 1, 2, '追い越し時のハイビームは相手を眩惑させ、事故を誘発する危険な行為です。合図は方向指示器のみで行います。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '霧のときは、自分の車の存在を周囲に知らせるため、前照灯を点灯するだけでなく、必要に応じてフォグランプやハザードランプを併用する。', '["○（正しい）","×（誤り）"]', 0, 2, '視界が悪い状況では、他車からの被視認性を高めることが重要です。適切な灯火類の使用は事故防止に直結します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '夜間、交通量の多い市街地を走行するときは、周囲の迷惑にならないよう、常に前照灯を消してスモールランプだけで走行する。', '["○（正しい）","×（誤り）"]', 1, 1, 'スモールランプ（車幅灯）は周囲に存在を知らせるためのもので、前方を照らすためのものではありません。夜間は必ず前照灯を点灯します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '雨の日は視界が悪くなるため、ワイパーを動かすだけでなく、前照灯を早めに点灯して自分の存在を周囲に知らせる。', '["○（正しい）","×（誤り）"]', 0, 1, '雨天時は昼間でも視界が悪くなります。早めのライト点灯は、他車や歩行者からの発見を早め、事故を未然に防ぐ効果があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '凍結路面でスタッドレスタイヤを装着していれば、どんなにスピードを出してもスリップすることはない。', '["○（正しい）","×（誤り）"]', 1, 1, 'スタッドレスタイヤは滑りにくいだけであり、過信は禁物です。凍結路面ではタイヤの性能に関わらず慎重な運転が必要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '夜間、交差点で右折するときは、対向車のライトが眩しくて距離感がつかみにくいため、無理をせず対向車をやり過ごしてから右折する。', '["○（正しい）","×（誤り）"]', 0, 2, '夜間の右折は距離感の誤認が多発します。対向車の速度や距離を正確に判断できない場合は、安全を優先して待機するのが正解です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '雪道でタイヤチェーンを装着した場合は、乾燥した舗装路面に出ても、そのままの速度で走行し続けてよい。', '["○（正しい）","×（誤り）"]', 1, 2, 'チェーン装着時は速度を落とさなければならず、また乾燥路面ではチェーンが損傷しやすいため、雪のない場所では外すのが基本です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '夜間、歩行者が反射材を身につけていれば、運転者は遠くからでも歩行者を容易に発見できるため、速度を落とす必要はない。', '["○（正しい）","×（誤り）"]', 1, 2, '反射材は発見の助けにはなりますが、万能ではありません。夜間は歩行者の発見が遅れることを前提に、常に速度を落として警戒すべきです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '雨の日にマンホールや白線の上を通過するときは、滑りやすくなっているため、急ハンドルや急ブレーキを避けて慎重に通過する。', '["○（正しい）","×（誤り）"]', 0, 1, 'マンホールや道路標示（白線）は、濡れると非常に滑りやすくなります。二輪車だけでなく四輪車にとっても危険なポイントです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '霧が非常に濃く、前方がほとんど見えないときは、道路の左端に寄せて停車し、霧が晴れるのを待つのが安全である。', '["○（正しい）","×（誤り）"]', 0, 2, '走行が困難なほどの濃霧では、無理に運転を続けるのは危険です。安全な場所に停車して待機するのが最も賢明な判断です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '夜間、照明のないトンネル内を走行するときは、前照灯を点灯しなくても周囲が見えるため、消灯して走行してもよい。', '["○（正しい）","×（誤り）"]', 1, 1, 'トンネル内は昼夜を問わず、また照明の有無に関わらず、前照灯を点灯しなければなりません。これは法令上の義務です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '雨の日に自転車を追い越す際は、路面が滑りやすく自転車がふらつく可能性があるため、十分な側方間隔をあけるか、速度を落として追い越す。', '["○（正しい）","×（誤り）"]', 0, 2, '自転車の転倒リスクが高まる雨天時は、より慎重な追い越しが求められます。側方間隔の確保は自転車保護の基本です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '夜間、バックするときは、後方の視界が極端に悪くなるため、窓を開けて音を聞いたり、必要に応じて車から降りて安全確認を行う。', '["○（正しい）","×（誤り）"]', 0, 2, '夜間の後退は死角が増えます。バックモニターに頼りすぎず、直接目視や音での確認を併用し、不安な場合は降車して確認すべきです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '雪道でスタック（動けなくなること）したときは、アクセルを強く踏み込み、勢いをつけて脱出するのが最も効果的である。', '["○（正しい）","×（誤り）"]', 1, 2, 'アクセルを強く踏むとタイヤが空転して雪を掘り下げ、さらに深く埋まってしまいます。低速でゆっくりと前後させるのが脱出のコツです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '夜間、対向車とすれ違う際にハイビームのまま走行することは、相手の運転を妨げるだけでなく、法的な違反行為である。', '["○（正しい）","×（誤り）"]', 0, 1, '道路交通法では、対向車と行き違う際や先行車の直後を走行する際は、前照灯を減光または下向きに切り替えることが義務付けられています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '雨の日にフロントガラスが曇ったときは、エアコンのデフロスター（除湿機能）を使用して視界を確保する。', '["○（正しい）","×（誤り）"]', 0, 1, '雨天時は車内の湿度が高まり曇りやすくなります。視界不良は事故の元ですので、デフロスターを適切に使用して視界をクリアに保ちます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '夜間、街灯が並んでいる道路であれば、自分の車のライトを消して走行しても、周囲から自分の車は十分に見えている。', '["○（正しい）","×（誤り）"]', 1, 1, '街灯の明るさは前照灯の代わりにはなりません。夜間は周囲の状況に関わらず、自車の存在を知らせるために前照灯の点灯が必須です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', 'カーブを曲がるときに働く遠心力は、速度の2乗に比例して大きくなるため、速度を2倍にすると遠心力は4倍になる。', '["○（正しい）","×（誤り）"]', 0, 2, '遠心力は速度の2乗に比例します。速度を上げると遠心力は急激に増大するため、カーブの手前では十分に減速することが不可欠です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', 'カーブを走行中、遠心力によって車が外側に膨らみそうになったときは、急ブレーキをかけて速度を落とすべきである。', '["○（正しい）","×（誤り）"]', 1, 2, 'カーブ中での急ブレーキはタイヤのグリップ力を失わせ、スリップや横転の原因となります。カーブに入る前に減速を完了させるのが鉄則です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', 'ハイドロプレーニング現象は、タイヤの溝が浅くなっているときや、空気圧が低いときに発生しやすくなる。', '["○（正しい）","×（誤り）"]', 0, 1, 'タイヤの排水性能が低下すると、路面とタイヤの間に水膜が入り込みやすくなります。タイヤの整備不良は事故に直結します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', 'ハイドロプレーニング現象が発生してハンドルやブレーキが効かなくなったときは、ハンドルを左右に大きく切って路面との摩擦を回復させるべきである。', '["○（正しい）","×（誤り）"]', 1, 2, '水膜の上ではハンドル操作は無効です。急な操作はグリップが回復した瞬間に車が急激な挙動を示すため、ハンドルを真っ直ぐに保ち、自然に減速を待ちます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '長い下り坂でフットブレーキを使いすぎると、ブレーキ液の中に気泡が発生するベーパーロック現象が起こり、ブレーキが効かなくなることがある。', '["○（正しい）","×（誤り）"]', 0, 1, 'ブレーキ液が過熱して沸騰し、気泡ができることで油圧が伝わらなくなる現象です。長い下り坂ではエンジンブレーキを併用する必要があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', 'フェード現象とは、ブレーキをかけすぎて摩擦材が過熱し、ブレーキの効きが悪くなる現象のことである。', '["○（正しい）","×（誤り）"]', 0, 1, 'フェード現象は摩擦材の過熱による効力低下、ベーパーロック現象はブレーキ液の沸騰による油圧伝達不良を指します。両方とも下り坂での多用が原因です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '下り坂でフェード現象やベーパーロック現象が疑われる場合は、すぐにサイドブレーキを強く引き、車を停止させるべきである。', '["○（正しい）","×（誤り）"]', 1, 3, '走行中に急激なサイドブレーキ操作を行うと、車がスピンして非常に危険です。エンジンブレーキを最大限に活用し、安全な場所に停止させるよう努めます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '雨の日は路面が滑りやすいため、晴天時よりも車間距離を長めにとり、急な操作を避ける必要がある。', '["○（正しい）","×（誤り）"]', 0, 1, '雨天時は制動距離が伸びるため、通常より余裕を持った車間距離が必要です。また、急ブレーキや急ハンドルはスリップを誘発します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', 'カーブの手前で減速するのは、遠心力を小さくして車が外側に膨らむのを防ぐためである。', '["○（正しい）","×（誤り）"]', 0, 1, '遠心力は速度の2乗に比例するため、速度を落とすことが最も効果的な対策です。カーブの曲率に合わせて適切な速度で進入します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '積雪や凍結した道路では、タイヤのグリップ力が低下するため、急発進や急ブレーキを避けてゆっくりと走行する必要がある。', '["○（正しい）","×（誤り）"]', 0, 1, '雪道や凍結路面ではタイヤが空転しやすく、制動距離も大幅に伸びます。低速で走行し、車間距離を十分にとることが重要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '霧が発生しているときは、視界が悪くなるため、ライトを点灯して自分の存在を周囲に知らせる必要がある。', '["○（正しい）","×（誤り）"]', 0, 1, '霧の中では前照灯を点灯し、必要に応じてフォグランプを使用します。視界が極端に悪い場合は、安全な場所に停車することも検討します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '夜間のカーブでは、前照灯がカーブの外側を照らしてしまうため、昼間よりも速度を落として慎重に走行しなければならない。', '["○（正しい）","×（誤り）"]', 0, 2, '夜間は前照灯の照射範囲が限られ、カーブの先が見えにくくなります。視界が制限されるため、昼間以上に減速して走行する必要があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', 'ハイドロプレーニング現象は、高速走行時だけでなく、低速走行時でも発生する可能性がある。', '["○（正しい）","×（誤り）"]', 1, 2, 'ハイドロプレーニング現象は、ある程度の速度が出ていないと発生しません。一般的には時速80km以上で発生しやすいとされますが、過信は禁物です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '下り坂でエンジンブレーキを使用すると、フットブレーキの負担が減り、フェード現象やベーパーロック現象の予防になる。', '["○（正しい）","×（誤り）"]', 0, 1, 'エンジンブレーキは摩擦熱を発生させないため、ブレーキ装置を保護する有効な手段です。長い下り坂では積極的に活用すべきです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '雨の降り始めは、路面のほこりや油分が浮き上がり、最も滑りやすくなるため特に注意が必要である。', '["○（正しい）","×（誤り）"]', 0, 2, '雨が降り始めると、路面上の油分が水と混ざり、非常に滑りやすい状態になります。このタイミングでの急操作は非常に危険です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', 'カーブを曲がる際、ハンドルを小刻みに動かすと、タイヤのグリップ力が維持されやすくなり、安定して曲がることができる。', '["○（正しい）","×（誤り）"]', 1, 2, 'カーブではハンドルを一定の角度で保持するのが基本です。小刻みな操作は車の挙動を不安定にし、スリップの原因となります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', 'ベーパーロック現象は、ブレーキ液の中に気泡が入ることで起こるため、定期的なブレーキ液の交換で予防できる。', '["○（正しい）","×（誤り）"]', 0, 2, 'ブレーキ液は吸湿性があり、劣化すると沸点が下がります。定期的な点検と交換は、ブレーキトラブルを防ぐための重要な整備です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '強い横風を受けているときは、ハンドルを風上側に少し切り、車が流されるのを防ぐ必要がある。', '["○（正しい）","×（誤り）"]', 0, 2, '橋の上やトンネルの出口など、横風が強い場所では車が流されやすいため、ハンドルをしっかり保持し、風の影響を予測して修正します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '雨の日にマンホールや白線の上を通る際は、摩擦係数が低いため、急ブレーキや急ハンドルを避ける。', '["○（正しい）","×（誤り）"]', 0, 1, 'マンホールや白線はアスファルトに比べて滑りやすくなっています。特に雨天時は非常に滑りやすいため、通過時は注意が必要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', 'フェード現象が発生したときは、すぐにギアをニュートラルに入れて、惰性で走行しブレーキを冷やすべきである。', '["○（正しい）","×（誤り）"]', 1, 3, '走行中にニュートラルに入れるとエンジンブレーキが効かなくなり、車を制御できなくなります。非常に危険な行為です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '雪道でスタックしたときは、アクセルを強く踏み込んで勢いよく脱出するのが最も効果的である。', '["○（正しい）","×（誤り）"]', 1, 2, 'アクセルを強く踏むとタイヤが空転し、雪を掘り下げてさらに深く埋まる原因になります。低速ギアでゆっくり発進するのが基本です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', 'カーブの手前で減速するのは、遠心力の影響を抑えるためだけでなく、カーブの先にある危険を察知するためでもある。', '["○（正しい）","×（誤り）"]', 0, 1, '減速することで視野が広がり、対向車や障害物への対応時間を確保できます。安全運転の基本です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', 'ハイドロプレーニング現象が発生した際、ABS（アンチロック・ブレーキ・システム）が作動していれば、ブレーキを強く踏み続けても安全である。', '["○（正しい）","×（誤り）"]', 1, 3, 'ABSはタイヤが接地している状態でのロックを防ぐ装置です。水膜の上でタイヤが浮いている状態では、ABSも効果を発揮できません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '下り坂でフットブレーキを多用すると、ブレーキの効きが悪くなるフェード現象が起こることがある。', '["○（正しい）","×（誤り）"]', 0, 1, 'ブレーキの摩擦熱が限界を超えると、摩擦材が熱変質して効きが悪くなります。これがフェード現象です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '夜間、対向車とすれ違うときは、前照灯を上向きに切り替えて、相手の車の位置をはっきりと確認する。', '["○（正しい）","×（誤り）"]', 1, 2, '対向車とすれ違うときは、相手を眩惑させないよう下向き（ロービーム）に切り替えるのがマナーであり、法令でも定められています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '雨の日の夜間は、路面の反射によって白線や歩行者が見えにくくなるため、より一層の注意が必要である。', '["○（正しい）","×（誤り）"]', 0, 1, '雨の夜は視界が悪化する要因が重なります。路面の反射で白線が見えにくくなるため、速度を落として慎重に運転します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '遠心力は、カーブの半径が小さいほど、また速度が速いほど大きくなる。', '["○（正しい）","×（誤り）"]', 0, 2, '遠心力はカーブの半径が小さい（急カーブ）ほど、また速度が速いほど強くなります。急なカーブでは特に減速が必要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '冬の山道では、日陰の道路が凍結している可能性があるため、日向と同じ感覚で走行してはならない。', '["○（正しい）","×（誤り）"]', 0, 1, '日陰は気温が低く、路面が凍結している可能性が高いです。路面状況の変化を予測して運転することが重要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', 'ブレーキをかけた際、タイヤがロックして滑り出したときは、ブレーキを一度緩めてから再度踏み直すと制御しやすくなる。', '["○（正しい）","×（誤り）"]', 0, 2, 'ポンピングブレーキと呼ばれる手法です。タイヤがロックすると操舵不能になるため、一度緩めてグリップを回復させるのが有効です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '霧で視界が悪いときは、前の車の尾灯を頼りに、できるだけ車間距離を詰めて走行すると安全である。', '["○（正しい）","×（誤り）"]', 1, 2, '前の車に頼りすぎると、急ブレーキに対応できず追突事故を起こす危険があります。視界が悪いときは、十分な車間距離をとるのが鉄則です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '自動車の日常点検は、運行の直前に行う必要があり、その内容はブレーキの効き具合やタイヤの空気圧、溝の深さなどが含まれる。', '["○（正しい）","×（誤り）"]', 0, 1, '日常点検は運行の直前に実施し、ブレーキ、タイヤ、エンジンオイル量などを確認することが義務付けられています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', 'タイヤの溝の深さは、全周にわたって1.6mm以上なければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '保安基準により、タイヤの溝の深さは全周にわたって1.6mm以上であることが規定されています。スリップサインが出ている場合は不適合です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '中央線や車両通行帯のない一般道路（生活道路）における法定最高速度は、時速60kmである。', '["○（正しい）","×（誤り）"]', 1, 2, '2026年9月施行の改正法により、中央線等のない生活道路の法定最高速度は時速30kmに引き下げられました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', 'マイナ免許証を選択した場合、従来のプラスチック製免許証は一切交付されない。', '["○（正しい）","×（誤り）"]', 1, 2, 'マイナ免許証制度では「従来免許証のみ」「マイナ免許証のみ」「両方持ち」の3つの選択肢があり、従来免許証も選択可能です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '普通免許の学科試験は、17歳6か月以上であれば受験が可能である。', '["○（正しい）","×（誤り）"]', 0, 2, '2026年4月施行の改正により、受験資格が17歳6か月以上に緩和されました。ただし、免許証の交付は18歳からです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '自転車の交通違反に対する青切符制度は、14歳以上のすべての自転車利用者が対象である。', '["○（正しい）","×（誤り）"]', 1, 2, '2026年4月施行の青切符制度は、16歳以上の自転車利用者が対象です。16歳未満は対象外となります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '自動車で自転車を追い越す際は、常に時速10km以下に減速しなければならない。', '["○（正しい）","×（誤り）"]', 1, 2, '追い越し時は「十分な側方間隔」または「安全な速度」で進行することが求められます。常に時速10km以下という規定はありません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '日常点検において、タイヤに亀裂やコードが露出している場合は、溝の深さが1.6mm以上あっても使用してはならない。', '["○（正しい）","×（誤り）"]', 0, 1, '溝の深さだけでなく、外傷やコード露出があるタイヤは保安基準を満たさないため、使用してはいけません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '運転免許の更新期間は、誕生日の前後1か月、計2か月間である。', '["○（正しい）","×（誤り）"]', 0, 1, '免許の更新期間は、誕生日の1か月前から1か月後までの計2か月間です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '交通違反の点数制度において、累積点数が一定に達すると免許の停止処分を受けるが、過去の違反歴がない場合は点数がリセットされる。', '["○（正しい）","×（誤り）"]', 1, 2, '点数制度は過去の違反歴や処分歴を考慮して累積されます。違反がない期間が一定以上続くとリセットされる特例はありますが、自動ではありません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', 'タイヤの空気圧は、指定された数値よりも高めに入れておくと、燃費が良くなるため常に高圧に保つべきである。', '["○（正しい）","×（誤り）"]', 1, 2, 'タイヤの空気圧は車両指定の適正値に保つべきです。高すぎると接地面積が減り、制動距離が伸びるなど危険です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '免許証の住所変更は、転居してから15日以内に行わなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '住所や氏名に変更があった場合は、速やかに（道路交通法上は遅滞なく）変更手続きを行う必要があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '中央線がある一般道路の法定最高速度は、時速50kmである。', '["○（正しい）","×（誤り）"]', 1, 1, '中央線や車両通行帯のある一般道路の法定最高速度は時速60kmです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', 'マイナ免許証を保有している場合、警察官から提示を求められた際は、スマートフォン等の画面を表示することで提示義務を果たせる。', '["○（正しい）","×（誤り）"]', 0, 2, 'マイナ免許証はデジタル化されており、所定のアプリ等で提示することで免許証の提示義務を満たします。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '日常点検は、車を使用する頻度に関わらず、毎日必ず実施しなければならない。', '["○（正しい）","×（誤り）"]', 1, 2, '日常点検は「運行の直前」に行うものです。車を使用しない日は実施する必要はありません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', 'タイヤの溝が1.6mm未満になると、雨天時にハイドロプレーニング現象が発生しやすくなる。', '["○（正しい）","×（誤り）"]', 0, 1, '溝が浅いと排水性能が低下し、濡れた路面でタイヤが浮くハイドロプレーニング現象が発生しやすくなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '免許の点数制度において、軽微な違反を繰り返した場合、累積点数が6点に達すると免許停止処分となる。', '["○（正しい）","×（誤り）"]', 0, 2, '累積点数が6点に達すると、30日間の免許停止処分となります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '17歳6か月で仮免許を取得した場合、路上練習は指導員が同乗していれば可能である。', '["○（正しい）","×（誤り）"]', 0, 2, '仮免許取得後は、指導員や免許取得後3年以上の者が同乗するなどの条件を満たせば路上練習が可能です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '自転車の青切符制度は、すべての交通違反に対して適用される。', '["○（正しい）","×（誤り）"]', 1, 2, '青切符制度は比較的軽微な違反が対象です。重大な違反や危険な違反は、従来通り赤切符（刑事罰）の対象となります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', 'タイヤの空気圧は、走行直後のタイヤが温まっている状態で測定するのが最も正確である。', '["○（正しい）","×（誤り）"]', 1, 2, 'タイヤの空気圧は、走行前の冷えている状態で測定するのが基本です。温まると空気が膨張し、正確な値になりません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '免許証の更新時に視力検査に合格しなかった場合、直ちに免許は取り消される。', '["○（正しい）","×（誤り）"]', 1, 2, '視力検査に合格しなかった場合、直ちに取消しにはなりませんが、再検査を受けるか、眼鏡等の条件を付加する手続きが必要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '中央線等のない生活道路において、時速30kmを超えて走行することは、道路標識等で指定がない限り違反である。', '["○（正しい）","×（誤り）"]', 0, 2, '2026年9月施行の改正により、生活道路の法定最高速度は時速30kmとなりました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '日常点検において、エンジンオイルの量はオイルレベルゲージの「F」と「L」の間にあることを確認する。', '["○（正しい）","×（誤り）"]', 0, 1, 'エンジンオイル量はレベルゲージで確認し、F（Full）とL（Low）の間にあれば適正です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', 'マイナ免許証を選択した場合、免許証の有効期限は従来の免許証と異なる。', '["○（正しい）","×（誤り）"]', 1, 2, 'マイナ免許証を選択しても、免許証の有効期限や更新期間のルールは変わりません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '自転車を追い越す際、十分な側方間隔が取れない場合は、自転車の速度に合わせて徐行しなければならない。', '["○（正しい）","×（誤り）"]', 0, 2, '安全な側方間隔が取れない場合は、安全な速度まで減速し、自転車の動きに注意して追い越す必要があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', 'タイヤの溝の深さを測る際は、スリップサインが出ている箇所を避けて測定する。', '["○（正しい）","×（誤り）"]', 1, 1, 'スリップサインは溝の深さが1.6mmになったことを示す指標であり、その箇所を含めて点検する必要があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '免許の点数制度において、過去3年以上無事故無違反の者が軽微な違反をした場合、点数が加算されない特例がある。', '["○（正しい）","×（誤り）"]', 0, 2, '3年以上無事故無違反の者が、軽微な違反（3点以下）をした場合、一定期間後に点数が累積されない特例があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '18歳未満であっても、普通免許を取得していれば、原付免許を別途取得する必要はない。', '["○（正しい）","×（誤り）"]', 0, 1, '普通免許を取得していれば、原付免許の範囲も運転できるため、別途取得する必要はありません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '日常点検でブレーキペダルを踏んだとき、床との間に十分な隙間があるかを確認するのは誤りである。', '["○（正しい）","×（誤り）"]', 1, 1, 'ブレーキペダルの踏みしろ（遊び）と、踏み込んだ時の床との隙間を確認することは、ブレーキの点検として必須です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '免許証の更新を忘れて有効期限が切れた場合、直ちに無免許運転となる。', '["○（正しい）","×（誤り）"]', 0, 1, '免許証の有効期限が1日でも過ぎれば、その時点で免許は失効しており、運転すれば無免許運転となります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '交通事故を起こしたときは、直ちに運転を停止し、負傷者を救護し、道路における危険を防止する措置を講じなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '道路交通法第72条に規定される、交通事故時の運転者の義務です。負傷者の救護と危険防止措置は最優先事項です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '交通事故の負傷者が意識を失っている場合、直ちに車で病院へ運ぶのが最も適切な救護措置である。', '["○（正しい）","×（誤り）"]', 1, 2, '負傷者をむやみに動かすと症状を悪化させる恐れがあります。まずは119番通報し、救急車の到着を待つのが原則です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '交通事故を起こした際、警察官が現場に到着する前であっても、負傷者の救護を優先しなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '警察への報告義務と救護義務は並行しますが、人命救助が最優先です。警察を待たずに救護活動を行う必要があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', 'AED（自動体外式除細動器）は、電源を入れた後は音声ガイダンスに従って操作すれば、専門知識がなくても使用できる。', '["○（正しい）","×（誤り）"]', 0, 1, 'AEDは一般市民が使用することを想定して設計されており、音声指示に従うことで安全かつ適切に使用可能です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '胸骨圧迫を行う際は、負傷者の胸が約3cm沈む程度の強さで、1分間に約60回のペースで行う。', '["○（正しい）","×（誤り）"]', 1, 2, '胸骨圧迫は「約5cm」沈む強さで、1分間に「100〜120回」のテンポで行うのが現在のガイドラインです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '交通事故現場で負傷者の気道を確保する場合、頭部を後ろに反らせてあごを突き上げる方法が有効である。', '["○（正しい）","×（誤り）"]', 0, 2, '頭部後屈あご先挙上法は、気道を確保するための標準的な手法です。ただし、頸椎損傷の疑いがある場合は注意が必要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '交通事故で負傷者が車内に閉じ込められている場合、救急隊の到着を待たずに無理に引きずり出して救助しなければならない。', '["○（正しい）","×（誤り）"]', 1, 2, '車両火災の危険があるなど緊急性が高い場合を除き、無理な救出は負傷者の状態を悪化させるため避けるべきです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '交通事故を起こした際、相手が「大丈夫です」と言ったので、警察に届け出ずその場で示談をして立ち去った。', '["○（正しい）","×（誤り）"]', 1, 1, '事故の大小に関わらず警察への報告義務があります。報告を怠ると報告義務違反（当て逃げ等）になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', 'AEDを使用する際、負傷者の胸が濡れている場合は、タオルなどで拭き取ってからパッドを貼り付ける。', '["○（正しい）","×（誤り）"]', 0, 2, '水分が残っていると通電が妨げられたり、火傷の原因になったりするため、必ず拭き取ってから装着します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '胸骨圧迫を続ける中で、負傷者が急に動き出したり、うめき声を上げたりした場合は、直ちに圧迫を中止して様子を見る。', '["○（正しい）","×（誤り）"]', 0, 2, '反応や回復の兆候が見られた場合は、胸骨圧迫を中止し、呼吸の状態を確認しながら救急隊の到着を待ちます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '交通事故の現場で、二次的な事故を防ぐために停止表示板や発炎筒を使用して、後続車に事故の発生を知らせる必要がある。', '["○（正しい）","×（誤り）"]', 0, 1, '道路における危険防止措置の一環として、後続車への合図は非常に重要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '人工呼吸を行う際、負傷者の口から異物が見えた場合は、無理に指でかき出さずそのまま人工呼吸を行う。', '["○（正しい）","×（誤り）"]', 1, 2, '異物が見える場合は、指でかき出すなどして除去してからでないと、気道閉塞を招く恐れがあります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '交通事故の負傷者が意識不明で呼吸をしていない場合、胸骨圧迫と人工呼吸を組み合わせて行う必要がある。', '["○（正しい）","×（誤り）"]', 0, 2, '心肺停止状態では、胸骨圧迫を中心とした心肺蘇生法が推奨されます。人工呼吸の技術に自信がない場合は胸骨圧迫のみでも可です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', 'AEDのパッドを貼る際、負傷者の胸に貼り薬がある場合は、そのままパッドを重ねて貼り付けても問題ない。', '["○（正しい）","×（誤り）"]', 1, 3, '貼り薬は火傷の原因になるため、必ず剥がしてから皮膚を拭いてパッドを貼る必要があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '負傷者の救護措置を講じている間、自分の車のエンジンはかけたままにしておくのが望ましい。', '["○（正しい）","×（誤り）"]', 1, 2, '安全のため、エンジンを切り、パーキングブレーキを確実にかけ、ハザードランプを点灯させるのが基本です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', 'AEDは、心室細動を起こしている心臓に電気ショックを与えて、正常なリズムに戻すための装置である。', '["○（正しい）","×（誤り）"]', 0, 1, 'AEDの目的は、心臓の電気的な乱れをリセットし、正常な拍動を取り戻すことです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '交通事故で出血が激しい場合、清潔な布で傷口を直接強く圧迫する「直接圧迫止血法」を行う。', '["○（正しい）","×（誤り）"]', 0, 1, '直接圧迫止血法は、誰にでもできる最も効果的な止血方法です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', 'AEDの解析中に負傷者に触れても、電気ショックの精度には影響がない。', '["○（正しい）","×（誤り）"]', 1, 2, '解析中に触れると誤判定の原因になるため、誰も負傷者に触れてはいけません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '負傷者が子供の場合、大人用のAEDパッドは使用してはならない。', '["○（正しい）","×（誤り）"]', 1, 3, '小児用パッドがない場合は、大人用パッドを代用して使用可能です。救命を優先します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '交通事故の負傷者を救護する際、自分の安全を確保することは二の次である。', '["○（正しい）","×（誤り）"]', 1, 2, '救助者が二次被害に遭っては元も子もありません。まずは自身の安全確保が最優先です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '心肺蘇生法を行っている最中に、救急隊が到着した場合は、直ちに引き継いで指示に従う。', '["○（正しい）","×（誤り）"]', 0, 1, '専門家である救急隊に速やかに引き継ぐことが、負傷者の救命率向上につながります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '交通事故で負傷者が意識を失っている場合、人工呼吸を行う前に気道確保を行う必要がある。', '["○（正しい）","×（誤り）"]', 0, 2, '気道が塞がっていると空気が肺に届かないため、人工呼吸の前には必ず気道確保が必要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', 'AEDは、負傷者が心臓発作を起こしているかどうかを自動的に判断する。', '["○（正しい）","×（誤り）"]', 0, 1, 'AEDは心電図を解析し、電気ショックが必要か否かを自動で判断します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '交通事故の負傷者が骨折している疑いがある場合、無理に姿勢を変えたり、患部を動かしたりしてはならない。', '["○（正しい）","×（誤り）"]', 0, 2, '骨折部位を動かすと、神経や血管を損傷する恐れがあるため、そのままの姿勢で救急隊を待ちます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '胸骨圧迫を続ける際、疲労によって圧迫の強さが弱まっても、休憩を取らずに続けるべきである。', '["○（正しい）","×（誤り）"]', 1, 2, '圧迫の質が低下すると効果がありません。周囲に人がいれば交代し、質の高い圧迫を維持する必要があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '交通事故の現場で、負傷者の意識を確認するために、頬を叩いたり強く揺さぶったりする。', '["○（正しい）","×（誤り）"]', 1, 2, '強く揺さぶることは頸椎損傷を悪化させる危険があるため、肩を軽く叩きながら呼びかけるのが適切です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', 'AEDによる電気ショックを行った後は、すぐに胸骨圧迫を再開する。', '["○（正しい）","×（誤り）"]', 0, 2, '電気ショック直後は心臓が正常なリズムに戻りやすいため、間髪入れずに胸骨圧迫を再開します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '交通事故で負傷者が嘔吐している場合、窒息を防ぐために横向きに寝かせる「回復体位」をとらせるのが有効である。', '["○（正しい）","×（誤り）"]', 0, 2, '回復体位は気道を確保し、嘔吐物による窒息を防ぐための適切な体位です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '負傷者の救護のために、自分の車を道路の真ん中に停車させたままにしておいてもよい。', '["○（正しい）","×（誤り）"]', 1, 2, '安全な場所へ移動できる場合は移動させ、交通の妨げにならないようにする必要があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '交通事故の負傷者に対し、AEDのパッドを貼る際、胸の毛が濃い場合は、パッドを強く押し付けて密着させる。', '["○（正しい）","×（誤り）"]', 1, 3, '毛が濃いと密着せず通電しません。付属の剃刀で剃るか、予備のパッドを貼って剥がすなどして毛を取り除きます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '原動機付自転車は、道路の左側端に寄って通行しなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '原動機付自転車は、道路の左側端に寄って通行する義務があります。これは二輪車特有の通行ルールです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '特定小型原動機付自転車（電動キックボード等）は、普通自転車専用通行帯を通行することができる。', '["○（正しい）","×（誤り）"]', 0, 2, '特定小型原動機付自転車は、自転車道や普通自転車専用通行帯を通行することが認められています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '二輪車で走行中、渋滞している車列の間をすり抜けて進むことは、安全であれば積極的に行うべきである。', '["○（正しい）","×（誤り）"]', 1, 1, 'すり抜け走行は極めて危険であり、交通ルール上も推奨されません。車列の間を通行することは避けましょう。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '特定小型原動機付自転車は、歩道を通行できる場合がある。', '["○（正しい）","×（誤り）"]', 0, 2, '特例特定小型原動機付自転車として基準を満たし、最高速度表示灯を点滅させている場合は、歩道を通行できます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '二輪車は、四輪車よりも死角が少ないため、追い越しや追い抜きを頻繁に行っても安全である。', '["○（正しい）","×（誤り）"]', 1, 1, '二輪車は車体が小さく、他車から見落とされやすいため、追い越し等の際はより慎重な判断が必要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '原動機付自転車の法定最高速度は、道路の状況に関わらず時速30kmである。', '["○（正しい）","×（誤り）"]', 0, 1, '原動機付自転車の法定最高速度は時速30kmです。道路の区分に関わらずこの制限速度が適用されます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '二輪車でカーブを曲がる際は、ブレーキをかけながら進入するのが最も安全である。', '["○（正しい）","×（誤り）"]', 1, 2, 'カーブ進入前に十分に減速を終え、カーブ内ではブレーキをかけないのが基本です。車体が不安定になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '特定小型原動機付自転車を運転する際、ヘルメットの着用は努力義務である。', '["○（正しい）","×（誤り）"]', 0, 2, '特定小型原動機付自転車のヘルメット着用は努力義務ですが、自身の安全のために着用が強く推奨されます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '二輪車は、中央線のある道路でも、右側部分にはみ出して追い越しをしてはならない。', '["○（正しい）","×（誤り）"]', 0, 2, '追い越し禁止場所や中央線がある道路では、右側にはみ出しての追い越しは禁止されています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '二輪車で二人乗りをする場合、運転免許を取得してから1年以上経過していれば、高速道路でも二人乗りができる。', '["○（正しい）","×（誤り）"]', 1, 3, '高速道路での二人乗りは、免許取得後3年以上かつ20歳以上である必要があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '原動機付自転車で二段階右折が必要な交差点では、交差点の直前まで左側に寄って直進し、交差点の向こう側で向きを変える。', '["○（正しい）","×（誤り）"]', 0, 2, '二段階右折のルール通り、交差点の端まで直進し、そこで向きを変えてから右折します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '特定小型原動機付自転車は、飲酒運転が禁止されている。', '["○（正しい）","×（誤り）"]', 0, 1, '特定小型原動機付自転車も車両の一種であり、飲酒運転は厳重に禁止されています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '二輪車で走行中、急ブレーキをかけるときは、前輪と後輪のブレーキを同時にバランスよくかけるのがよい。', '["○（正しい）","×（誤り）"]', 0, 2, '片方だけかけると転倒やスリップの危険があるため、両方のブレーキを適切に使うのが基本です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '原動機付自転車は、高速道路や自動車専用道路を通行することができる。', '["○（正しい）","×（誤り）"]', 1, 1, '原動機付自転車は高速道路や自動車専用道路を通行することはできません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '特定小型原動機付自転車は、16歳未満でも運転することができる。', '["○（正しい）","×（誤り）"]', 1, 2, '特定小型原動機付自転車は16歳以上でなければ運転できません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '二輪車は、渋滞している道路で路肩を通行して追い抜くことができる。', '["○（正しい）","×（誤り）"]', 1, 2, '路肩は緊急車両用や歩行者用であり、追い抜きのために通行することは禁止されています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '二輪車で走行中、雨の日はマンホールや白線の上でブレーキをかけると滑りやすいため注意が必要である。', '["○（正しい）","×（誤り）"]', 0, 1, 'マンホールや白線は摩擦係数が低く、雨天時は非常に滑りやすいため、避けて走行するか慎重に操作すべきです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '特定小型原動機付自転車は、運転免許がなくても運転できる。', '["○（正しい）","×（誤り）"]', 0, 2, '特定小型原動機付自転車は免許不要ですが、交通ルールを守る義務はあります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '二輪車は、追い越しをする際、前車の右側を通行しなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '追い越しは原則として前車の右側を通行します。左側からの追い越しは禁止されています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '原動機付自転車で交差点を右折する際、二段階右折の標識がない交差点では、自動車と同様に交差点の中心の内側を徐行して右折する。', '["○（正しい）","×（誤り）"]', 0, 2, '二段階右折の指定がない交差点では、原付も小回り右折が原則です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '二輪車は、エンジンを切って押して歩いているときは歩行者として扱われる。', '["○（正しい）","×（誤り）"]', 0, 2, 'エンジンを切り、乗車せずに押して歩いている場合は歩行者として扱われます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '特定小型原動機付自転車は、最高速度表示灯を点滅させていれば、歩道を通行できる。', '["○（正しい）","×（誤り）"]', 0, 2, '特例特定小型原動機付自転車として、歩道通行可能な条件を満たしている場合に限ります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '二輪車で走行中、後続車が追い越そうとしているときは、速度を上げて追い越しを妨害してはならない。', '["○（正しい）","×（誤り）"]', 0, 1, '追い越しを妨害する行為は禁止されています。道を譲るのが安全な運転です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '原動機付自転車は、一方通行の道路であっても、自転車専用の逆走通行帯があれば逆走できる。', '["○（正しい）","×（誤り）"]', 1, 3, '自転車専用の逆走通行帯はあくまで自転車用であり、原付は通行できません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '二輪車は、夜間は昼間よりも遠くからでも目立つため、ライトを消して走行してもよい。', '["○（正しい）","×（誤り）"]', 1, 1, '二輪車は車体が小さいため、夜間はライトを点灯して自車の存在を他車に知らせる必要があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '特定小型原動機付自転車は、道路交通法上の「軽車両」に分類される。', '["○（正しい）","×（誤り）"]', 1, 3, '特定小型原動機付自転車は「原動機付自転車」の一種であり、軽車両ではありません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '二輪車で走行中、前車が右折しようとしている場合、左側から追い越すことができる。', '["○（正しい）","×（誤り）"]', 1, 2, '前車が右折の合図を出している場合、左側からの追い越しは禁止されています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '原動機付自転車は、交通量の多い道路では、車道の真ん中を通行して安全を確保する。', '["○（正しい）","×（誤り）"]', 1, 1, '原付は左側端に寄って通行する義務があります。真ん中を通行するのは違反です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '二輪車で二人乗りをする場合、タンデムステップ（後部座席用ステップ）が装備されていなければならない。', '["○（正しい）","×（誤り）"]', 0, 2, '二人乗りには、同乗者が足を置くためのステップが必須です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '特定小型原動機付自転車で交差点を右折する際は、二段階右折をする必要がある。', '["○（正しい）","×（誤り）"]', 1, 2, '特定小型原動機付自転車は、二段階右折の対象外であり、小回り右折を行います。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '16歳以上の自転車運転者が交通違反をした場合、一定の要件を満たせば青切符（交通反則通告制度）の対象となる。', '["○（正しい）","×（誤り）"]', 0, 1, '2026年4月施行の改正道路交通法により、16歳以上の自転車利用者にも交通反則通告制度（青切符）が導入されました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '自転車は軽車両であるため、原則として道路の左側端に寄って通行しなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '自転車は軽車両であり、道路交通法上、左側通行が義務付けられています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '自転車で走行中、スマートフォンを手に持って通話や画面を注視する行為は、青切符の対象となる違反である。', '["○（正しい）","×（誤り）"]', 0, 2, '自転車の「ながらスマホ」は厳罰化されており、青切符の対象となる交通違反です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '自転車の酒気帯び運転は、自動車と同様に罰則の対象となる。', '["○（正しい）","×（誤り）"]', 0, 1, '自転車の酒気帯び運転は禁止されており、罰則が強化されています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '中央線や車両通行帯のない一般道路において、自動車の法定最高速度は時速60kmである。', '["○（正しい）","×（誤り）"]', 1, 2, '2026年9月施行の改正法により、中央線等のない一般道路の法定最高速度は時速30kmに引き下げられました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '自動車が自転車を追い越す際は、十分な側方間隔を空けるか、または安全な速度で進行しなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '2026年4月施行の改正法で、自転車追い越し時の安全確保義務がより明確化されました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '普通免許の仮免許試験を受験できるのは、18歳に達した日からである。', '["○（正しい）","×（誤り）"]', 1, 2, '2026年4月より、受験資格は17歳6か月以上に引き下げられました。交付は18歳からです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '自転車は歩道を通行できる場合があるが、その際は歩行者の通行を妨げてはならない。', '["○（正しい）","×（誤り）"]', 0, 1, '歩道通行が認められる場合でも、自転車は歩行者優先であり、徐行義務があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '自転車で信号機のある交差点を右折する場合、二段階右折をしなければならない。', '["○（正しい）","×（誤り）"]', 0, 2, '自転車は交差点で右折する際、二段階右折が義務付けられています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '自転車の酒気帯び運転を教唆（そそのかし）した者も罰則の対象となる。', '["○（正しい）","×（誤り）"]', 0, 3, '自転車の酒気帯び運転の提供や教唆も、道路交通法により厳しく処罰されます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '自転車で傘を差して運転することは、道路交通法上、全ての都道府県で禁止されている。', '["○（正しい）","×（誤り）"]', 0, 2, '傘差し運転は各都道府県の公安委員会規則により禁止されており、全国的に規制対象です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '自転車の青切符制度は、16歳未満の者に対しても適用される。', '["○（正しい）","×（誤り）"]', 1, 2, '青切符制度は16歳以上の自転車運転者が対象です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '中央線のある一般道路での法定最高速度は、時速60kmである。', '["○（正しい）","×（誤り）"]', 0, 1, '中央線等がある一般道路は、改正後も原則として時速60kmです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '自転車は、道路の右側を通行してもよい場合がある。', '["○（正しい）","×（誤り）"]', 1, 2, '自転車は軽車両であり、いかなる場合も左側通行が原則です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '自転車のながらスマホで事故を起こした場合、青切符ではなく赤切符（刑事罰）の対象となる可能性がある。', '["○（正しい）","×（誤り）"]', 0, 2, '軽微な違反は青切符ですが、事故を起こした場合は重い刑事罰（赤切符）の対象となります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '普通免許の試験は、17歳6か月に達していれば受験可能である。', '["○（正しい）","×（誤り）"]', 0, 1, '2026年4月施行の改正法により、受験資格が17歳6か月に引き下げられました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '自転車で歩道を走る際は、歩行者の通行を妨げる恐れがある場合でも、ベルを鳴らして警告すればよい。', '["○（正しい）","×（誤り）"]', 1, 2, 'ベルを鳴らすことは歩行者を威嚇する行為であり、歩道通行時は徐行して歩行者を優先すべきです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '自転車の青切符制度導入により、反則金を納付すれば刑事罰を免れることができる。', '["○（正しい）","×（誤り）"]', 0, 2, '交通反則通告制度の趣旨通り、反則金を納付すれば刑事手続きは終了します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '自転車は、車両通行帯のある道路では、左側の車両通行帯を通行しなければならない。', '["○（正しい）","×（誤り）"]', 0, 2, '自転車は軽車両として、最も左側の車両通行帯を通行する義務があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '酒気帯び状態で自転車を運転し、警察官の停止命令に従わなかった場合、罰則が加重される。', '["○（正しい）","×（誤り）"]', 0, 3, '警察官の指示に従わないことは、法令違反としてより重い罰則の対象となります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', 'マイナ免許証を所持していても、運転免許証の携帯義務は免除されない。', '["○（正しい）","×（誤り）"]', 1, 2, 'マイナ免許証を所持していれば、物理的な免許証の携帯義務は免除されます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '自転車で一時停止の標識がある場所では、必ず停止線で停止しなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '自転車も車両として、一時停止標識に従う義務があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '自動車が自転車を追い越す際、自転車との間に十分な側方間隔を空けられない場合は、追い越しを控えるべきである。', '["○（正しい）","×（誤り）"]', 0, 2, '安全な間隔が確保できない場合は、追い越しを中止するのが運転者の義務です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '自転車の青切符は、全ての交通違反に対して適用される。', '["○（正しい）","×（誤り）"]', 1, 2, '青切符は一定の軽微な違反が対象であり、重大な違反は引き続き赤切符となります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '中央線のない生活道路で時速40kmで走行する自転車を追い越す際、自動車は時速30km以下に減速する必要がある。', '["○（正しい）","×（誤り）"]', 1, 3, '追い越し時の義務は側方間隔の確保であり、速度制限の数値が自動的に決まるわけではありません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '自転車は、夜間は必ず前照灯を点灯しなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '夜間の灯火義務は自転車にも適用されます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '16歳未満の者が自転車で違反をした場合、青切符が交付される。', '["○（正しい）","×（誤り）"]', 1, 2, '青切符は16歳以上が対象であり、16歳未満は対象外です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '自動車の運転免許証は、マイナ免許証と従来型免許証を同時に所持することが可能である。', '["○（正しい）","×（誤り）"]', 0, 1, 'マイナ免許証と従来型免許証の併用（両方持ち）は可能です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '自転車の酒気帯び運転の罰則は、自動車の酒気帯び運転よりも軽い。', '["○（正しい）","×（誤り）"]', 1, 2, '自転車の酒気帯び運転も厳罰化されており、自動車と同等に厳しく処罰されます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '中央線や車両通行帯のない生活道路において、道路標識等による指定がない場合、法定最高速度は時速30kmである。', '["○（正しい）","×（誤り）"]', 0, 1, '2026年9月施行の改正道路交通法により、中央線等のない一般道路の法定速度は30km/hに引き下げられました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', 'ゾーン30の区域内では、道路標識等で指定されていなくても、すべての道路で最高速度は時速30kmに制限される。', '["○（正しい）","×（誤り）"]', 0, 1, 'ゾーン30は生活道路の安全確保を目的としており、区域内は原則として時速30kmの速度規制が適用されます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '6歳未満の幼児を乗車させる場合、チャイルドシートの使用が義務付けられているが、病気等のやむを得ない理由がある場合は免除される。', '["○（正しい）","×（誤り）"]', 0, 2, 'チャイルドシートは原則義務ですが、医学的な理由や座席の構造上設置が困難な場合など、法令で定められた例外があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '後部座席の同乗者がシートベルトを着用していない場合、運転者は違反点数を加算される可能性がある。', '["○（正しい）","×（誤り）"]', 0, 1, '全席シートベルト着用は義務です。運転者は同乗者に着用させる義務があり、違反すれば運転者の点数が加算されます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '自転車が前方を走行している場合、追い越す際は必ず一時停止しなければならない。', '["○（正しい）","×（誤り）"]', 1, 2, '追い越し時は一時停止ではなく、十分な側方間隔を空けるか、安全な速度で進行することが求められます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '普通免許の受験資格は、17歳6か月以上であれば試験を受けることができる。', '["○（正しい）","×（誤り）"]', 0, 2, '2026年4月施行の改正により、受験資格は17歳6か月以上に引き下げられました。ただし免許交付は18歳からです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '生活道路で子供が遊んでいるのを見かけたが、こちらに気づいていない様子だったので、速度を落とさずそのまま通過した。', '["○（正しい）","×（誤り）"]', 1, 1, '子供は予測不能な動きをするため、徐行や一時停止をして安全を確保しなければなりません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', 'チャイルドシートは、助手席に取り付けてもよい。', '["○（正しい）","×（誤り）"]', 1, 2, '助手席のエアバッグが作動した際の衝撃が危険なため、チャイルドシートは後部座席に取り付けるのが原則です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', 'マイナ免許証を保有している場合、従来の免許証を携帯する必要は一切ない。', '["○（正しい）","×（誤り）"]', 1, 2, 'マイナ免許証のみ、従来免許証のみ、両方持ちのいずれも可能です。従来免許証を携帯しない場合はマイナ免許証が必須です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '生活道路で歩行者のそばを通る際、安全な間隔がとれない場合は、一時停止しなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '安全な間隔を保てない場合は、徐行または一時停止して歩行者の安全を確保する義務があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', 'シートベルトを着用すると圧迫感があるため、短距離の移動であれば着用しなくてもよい。', '["○（正しい）","×（誤り）"]', 1, 1, '距離に関わらず、自動車に乗車する際は全席でシートベルトを着用しなければなりません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', 'ゾーン30の区域内では、自転車は歩道を通行してはならない。', '["○（正しい）","×（誤り）"]', 1, 3, 'ゾーン30は自動車の速度を規制するものであり、自転車の通行場所（歩道・車道）のルールは別途適用されます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '6歳未満の子供を抱っこして助手席に乗せることは、短時間であれば認められる。', '["○（正しい）","×（誤り）"]', 1, 1, '6歳未満の幼児はチャイルドシートの使用が必須であり、抱っこでの乗車は法令違反です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '生活道路で対向車とすれ違う際、道幅が狭い場合は、譲り合いの精神で安全な速度で進行する。', '["○（正しい）","×（誤り）"]', 0, 1, '狭い道路では譲り合いが基本です。危険を感じたら徐行し、安全を確認してから進行します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '自転車の交通違反に対する青切符制度は、16歳以上のすべての自転車利用者が対象である。', '["○（正しい）","×（誤り）"]', 0, 2, '2026年4月施行の改正法により、16歳以上の自転車利用者に対して青切符制度が導入されました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '生活道路の交差点では、見通しが悪くても一時停止の標識がなければ停止する必要はない。', '["○（正しい）","×（誤り）"]', 1, 2, '見通しの悪い交差点では、標識の有無に関わらず徐行し、安全を確認する義務があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', 'チャイルドシートは、身長や体重に合ったものを使用しなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, 'チャイルドシートは子供の体格に適合したものを使用しないと、事故時の安全性が確保されません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', 'シートベルトを着用していない同乗者がいる場合、運転者はその同乗者に着用を促さなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '運転者には同乗者にシートベルトを着用させる義務があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '生活道路において、歩行者が横断歩道付近で待っている場合、必ず一時停止して歩行者の横断を妨げてはならない。', '["○（正しい）","×（誤り）"]', 0, 1, '横断歩道は歩行者優先です。歩行者がいれば一時停止して道を譲る義務があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', 'ゾーン30の区域内では、自動車は時速30km以下で走行しなければならないため、歩行者に注意を払う必要はない。', '["○（正しい）","×（誤り）"]', 1, 1, '速度制限を守るだけでなく、常に歩行者等の周囲の安全に注意を払う必要があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '17歳6か月で普通免許を取得した場合、18歳になるまでは運転してはならない。', '["○（正しい）","×（誤り）"]', 1, 2, '免許証が交付されていれば運転可能です。受験資格が17歳6か月になっただけで、交付は18歳からです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '生活道路で自転車を追い越す際、十分な側方間隔がとれない場合は、無理に追い越さず安全な場所まで待つべきである。', '["○（正しい）","×（誤り）"]', 0, 2, '安全を確保できない追い越しは事故の元です。無理な追い越しは避けるのが鉄則です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', 'チャイルドシートは、レンタカーであっても使用義務がある。', '["○（正しい）","×（誤り）"]', 0, 1, '車両の所有形態に関わらず、6歳未満の幼児を乗せる場合はチャイルドシートが必要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', 'シートベルトの着用義務は、運転者と助手席のみである。', '["○（正しい）","×（誤り）"]', 1, 1, 'シートベルトは全席着用が義務付けられています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '生活道路で子供がボールを追いかけて飛び出してきた場合、急ブレーキをかけても間に合わない可能性があるため、最初から徐行しておくべきである。', '["○（正しい）","×（誤り）"]', 0, 1, '生活道路では子供の飛び出しを予測し、いつでも停止できる速度（徐行）で走行することが重要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', 'マイナ免許証を選択した場合、従来型の免許証は即座に廃棄しなければならない。', '["○（正しい）","×（誤り）"]', 1, 2, '従来免許証を保持し続けることも可能です。廃棄の義務はありません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', 'ゾーン30の標識がある場所では、自転車も時速30km以下で走行しなければならない。', '["○（正しい）","×（誤り）"]', 1, 3, 'ゾーン30の速度規制は自動車等（原付含む）が対象であり、自転車には直接適用されません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '6歳未満の子供がチャイルドシートを嫌がって泣く場合は、外してもよい。', '["○（正しい）","×（誤り）"]', 1, 1, 'いかなる理由があっても、6歳未満の幼児のチャイルドシート未着用は法令違反です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '生活道路で自転車が車道の右側を通行している場合、自動車は追い越してはならない。', '["○（正しい）","×（誤り）"]', 1, 2, '自転車は左側通行が原則ですが、右側通行している場合でも、安全に配慮して追い越すことは可能です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', 'シートベルトを着用していても、エアバッグがあれば事故時の安全は完全に確保される。', '["○（正しい）","×（誤り）"]', 1, 2, 'エアバッグはシートベルトの補助装置です。シートベルトを着用していないと、エアバッグの衝撃でかえって危険です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '中央線や車両通行帯のない一般道路（生活道路）において、標識等で指定がない場合、自動車の法定最高速度は時速60kmである。', '["○（正しい）","×（誤り）"]', 1, 3, '2026年9月施行の改正により、中央線等のない生活道路の法定最高速度は時速30kmに引き下げられました。原則の60km/hとは異なる点に注意が必要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '16歳以上の自転車運転者が信号無視をした場合、青切符による反則金制度の対象となる。', '["○（正しい）","×（誤り）"]', 0, 2, '2026年4月施行の改正により、16歳以上の自転車運転者にも青切符制度が導入されました。交通違反には反則金が科されるようになっています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '普通免許の学科試験は、満17歳6か月以上であれば受験することができる。', '["○（正しい）","×（誤り）"]', 0, 2, '2026年4月施行の改正により、受験資格が17歳6か月に引き下げられました。ただし、免許証の交付は18歳に達してからとなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '交差点で右折する際、対向車が直進してくる場合は、たとえ自車が先に交差点に入っていても対向車の進行を妨げてはならない。', '["○（正しい）","×（誤り）"]', 0, 1, '直進車優先の原則です。右折車は対向直進車の進行を妨げてはなりません。交差点進入の先後は関係ありません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '踏切を通過する際、変速装置の操作を確実に行うため、踏切内での変速は認められている。', '["○（正しい）","×（誤り）"]', 1, 1, '踏切内での変速はエンスト等の危険があるため禁止されています。踏切に入る前に適切なギアを選択しておく必要があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '徐行とは、ブレーキを踏んでから直ちに停止できる速度で進行することをいう。', '["○（正しい）","×（誤り）"]', 0, 1, '徐行の定義です。直ちに停止できる速度とは、概ね時速10km以下を指します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '追い越しを禁止されている場所であっても、前方の原動機付自転車が時速15kmで走行している場合は追い越すことができる。', '["○（正しい）","×（誤り）"]', 1, 2, '追い越し禁止場所では、相手の速度に関わらず追い越しは禁止です。原付であっても例外ではありません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '信号機のない横断歩道に歩行者がいる場合、一時停止して歩行者の通行を妨げないようにしなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '横断歩行者等妨害等違反の典型例です。歩行者がいれば必ず一時停止する義務があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '夜間、街灯がある道路を走行する場合、前照灯（ヘッドライト）は消灯してもよい。', '["○（正しい）","×（誤り）"]', 1, 1, '夜間は街灯の有無に関わらず、前照灯を点灯しなければなりません。消灯してよいのは昼間のみです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '警察官が手信号で停止の合図をしている場合、信号機の表示が青であっても警察官の指示に従わなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '警察官の手信号は信号機よりも優先されます。信号機が青であっても警察官の指示に従う必要があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '一方通行の道路では、道路の右側に駐車してもよい。', '["○（正しい）","×（誤り）"]', 1, 2, '駐車は道路の左端に沿って行う必要があります。一方通行であっても右側に駐車することは禁止されています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '高速道路の加速車線では、本線車道の交通を妨げないように加速して合流しなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '加速車線は本線の流れに乗るための場所です。本線車道の交通を妨げないよう、十分に加速して合流する義務があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '初心運転者標識（若葉マーク）を付けている車を追い越す際、幅寄せや割り込みをしてはならない。', '["○（正しい）","×（誤り）"]', 0, 1, '初心者マークの車に対する保護義務です。幅寄せや割り込みは禁止されており、違反すると罰則の対象となります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '雨の日にブレーキをかけると滑りやすいため、急ブレーキを避けるだけでなく、エンジンブレーキを併用することが望ましい。', '["○（正しい）","×（誤り）"]', 0, 1, '雨天時は路面が滑りやすいため、フットブレーキだけに頼らずエンジンブレーキを併用して減速するのが安全です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '追い越しをする際、前車が右折の合図を出している場合は、その右側を追い越すことができる。', '["○（正しい）","×（誤り）"]', 1, 2, '右折しようとしている車の右側を追い越すことは禁止されています。左側から追い越すのが原則です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '交差点で緊急自動車が接近してきた場合、交差点を避けて左側に寄って一時停止しなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '緊急自動車への進路譲り義務です。交差点内では交差点を通過し、左側に寄って停止します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', 'トンネル内では、故障等のやむを得ない場合を除き、駐車および停車をしてはならない。', '["○（正しい）","×（誤り）"]', 0, 2, 'トンネル内は駐停車禁止場所です。視界が悪く危険なため、法令で厳格に禁止されています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '免許証の更新期間が満了する日の年齢が70歳以上の人は、更新時に高齢者講習を受けなければならない。', '["○（正しい）","×（誤り）"]', 0, 2, '70歳以上の高齢者は免許更新時に高齢者講習の受講が義務付けられています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '運転中に携帯電話を使用することは、停止中であっても禁止されている。', '["○（正しい）","×（誤り）"]', 1, 2, '「運転中」とは走行中のことを指します。信号待ちなどで完全に停止している場合は使用禁止の対象外ですが、安全のため控えるべきです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '高速道路で故障して路肩に停止した際、車内に留まって救助を待つのが最も安全である。', '["○（正しい）","×（誤り）"]', 1, 2, '高速道路上で停止した場合は、速やかに車外の安全な場所（ガードレールの外側など）へ避難し、発炎筒等で後続車に合図を送る必要があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '標識で「車両進入禁止」とある場合、自転車も通行してはならない。', '["○（正しい）","×（誤り）"]', 0, 1, '車両進入禁止の標識は、自転車を含むすべての車両が対象です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '踏切の警報機が鳴っているときは、遮断機が降りていなければ進入してもよい。', '["○（正しい）","×（誤り）"]', 1, 1, '警報機が鳴っているときは、遮断機の有無に関わらず踏切内への進入は禁止されています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '追い越し禁止場所であっても、自転車を追い越す場合は例外として認められる。', '["○（正しい）","×（誤り）"]', 1, 2, '追い越し禁止場所では、対象が自転車であっても追い越しは禁止です。追い抜き（進路を変えずに追い越す）とは区別されます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '運転免許証の住所変更は、転居してから1か月以内に行わなければならない。', '["○（正しい）","×（誤り）"]', 1, 2, '住所変更は「速やかに」行う必要があります。1か月以内という期限は誤りです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '夜間、対向車と行き違うときは、前照灯を減光するか下向きに切り替えなければならない。', '["○（正しい）","×（誤り）"]', 0, 1, '対向車の眩惑を防ぐための義務です。夜間のすれ違い時は下向きにするのがルールです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '高速道路での法定最高速度は、標識で指定がない限り一律時速100kmである。', '["○（正しい）","×（誤り）"]', 1, 2, '高速道路の法定最高速度は車種によって異なります。普通乗用車は100km/hですが、大型貨物車などは異なるため「一律」は誤りです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_honmen', '追い越しをするときは、右側から追い越すのが原則である。', '["○（正しい）","×（誤り）"]', 0, 1, '追い越しは前車の右側を通るのが原則です。左側からの追い越しは原則禁止されています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_hazard', '住宅街で子供がボールを追いかけて道路に飛び出してきた。このとき、最も適切な行動はどれか。', '["急ブレーキをかけて停車する","警音器を鳴らして注意を促し、そのまま通過する","ハンドル操作で回避しながら加速する","徐行または停止できる速度で進行し、子供の動きに注視する"]', 3, 1, '子供の飛び出しは予測困難な危険です。急ブレーキは追突の恐れがあるため、常に停止できる速度で備えるのが原則です。', 'hazard_residential_ball');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_hazard', '交差点で右折しようとした際、対向直進の自転車が接近している。どうすべきか。', '["自転車の速度が遅いと判断し、先に右折する","自転車が通過するまで交差点内で待機する","自転車を威嚇するために軽く警音器を鳴らす","自転車の直前を急いで横切る"]', 1, 2, '右折車は直進車の進行を妨げてはなりません。自転車の速度や距離を誤認しやすいため、安全が確認できるまで待つのが鉄則です。', 'hazard_intersection_bike');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_hazard', '夜間の雨天時、対向車のライトが眩しく視界が悪い。どのような運転が適切か。', '["ハイビームにして視界を確保する","中央線寄りを走行して対向車を避ける","速度を落とし、道路左側の白線や縁石を目安に走行する","対向車のライトを直視して位置を把握する"]', 2, 2, '夜間の雨天は蒸発現象で白線が見えにくくなります。左側寄りを通行し、速度を落として視界不良に備えるのが安全です。', 'hazard_night_rain');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_hazard', '高速道路の合流地点で、本線へ合流する際の正しい方法はどれか。', '["本線を走行する車両の直前に割り込む","加速車線で十分に加速し、本線の流れに合わせて合流する","本線車両が譲ってくれることを期待して減速する","合流車線で一時停止してから合流する"]', 1, 1, '加速車線は本線の速度に合わせるためのものです。一時停止は後続車との追突事故を招くため、原則禁止です。', 'hazard_highway_merge');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_hazard', '通学バスが停車し、子供が乗り降りしている。追い越す際の注意点はどれか。', '["徐行して安全を確認しながら追い越す","バスが発車するまで待つ必要はないので、そのままの速度で通過する","警音器を鳴らして注意を促し、素早く追い越す","バスの陰から子供が飛び出す可能性があるため、一時停止して安全を確認する"]', 3, 2, '停車中の通学バス周辺は死角が多く、子供の飛び出しが非常に危険です。徐行だけでなく、一時停止による安全確認が必須です。', 'hazard_school_bus');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_hazard', '自転車を追い越す際、道路交通法に基づいた適切な側方間隔はどれか。', '["自転車との距離は気にせず、そのままの速度で通過する","自転車の幅に関わらず、常に1メートル以上の間隔を空ける","安全な速度と十分な側方間隔を確保して追い越す","自転車が左側に寄っているなら、間隔を詰めれば追い越してもよい"]', 2, 2, '2026年4月施行の改正法では、自転車追い越し時の側方間隔と安全速度の確保がより厳格に求められています。', 'hazard_bicycle_overtake');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_hazard', '中央線のない生活道路（時速30km規制）を走行中、前方に歩行者がいる。どうすべきか。', '["制限速度の30km/hまで加速して追い越す","歩行者との間に安全な間隔を空けられない場合は、一時停止して歩行者の通行を待つ","警音器を鳴らして歩行者に道を譲らせる","歩行者の後ろをぴったりついて走行する"]', 1, 1, '生活道路では歩行者優先です。安全な間隔が確保できない場合は、追い越しを控えるのが法令上の義務です。', 'hazard_residential_ball');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_hazard', '交差点で信号待ちをしている際、左折しようとする大型車がいる。どう対応すべきか。', '["大型車の内輪差を考慮し、停止線より後ろに下がって道を空ける","大型車が通れるスペースはあるので、そのまま待機する","大型車の動きに合わせて自分も少し前進する","大型車に早く曲がるよう合図を送る"]', 0, 2, '大型車の内輪差は大きく、巻き込み事故の危険があります。停止位置を下げて十分なスペースを確保することが重要です。', 'hazard_intersection_bike');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_hazard', '夜間、街灯のない道路で対向車とすれ違う際のライトの切り替えはどれか。', '["常にハイビームで走行する","すれ違う直前にロービームに切り替え、相手の幻惑を防ぐ","対向車が来るまで消灯する","対向車が来てもハイビームのまま走行する"]', 1, 1, '対向車のライトを眩しくさせるのは危険です。すれ違い時はロービームに切り替えるのがマナーであり法令上の配慮です。', 'hazard_night_rain');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_hazard', '高速道路で渋滞の最後尾に並ぶ際、最も適切な行動はどれか。', '["ハザードランプを点灯させ、後続車に渋滞を知らせる","急ブレーキをかけて停止する","渋滞の列には入らず、路肩を走行して先へ進む","車間距離を極端に詰めて停止する"]', 0, 1, '高速道路での追突事故を防ぐため、ハザードランプで後続車に注意を促すことは極めて重要です。', 'hazard_highway_merge');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_hazard', '通学バスがハザードランプを点滅させて停車している。このとき注意すべきことは。', '["バスは追い越してはいけないので、後ろで停車し続ける","バスの周囲から子供が飛び出す可能性があるため、徐行して通過する","バスの乗客が降り終わるまで警音器を鳴らし続ける","バスの左側から追い越す"]', 1, 2, '通学バス付近は子供の飛び出しが最も多い場所の一つです。徐行し、いつでも停止できる準備をして通過します。', 'hazard_school_bus');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_hazard', '自転車が前方を走行している。追い越す際の判断として正しいものは。', '["自転車がふらついている場合は、間隔を空けて追い越す","自転車が左側に寄っているなら、速度を落とさず追い越す","追い越しが困難な狭い道では、無理に追い越さず自転車の後方で待機する","自転車を追い越すために一時的に対向車線にはみ出す"]', 2, 2, '安全な間隔が確保できない状況で無理に追い越すのは違反です。状況に応じて待機する判断力が求められます。', 'hazard_bicycle_overtake');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_hazard', '住宅街の交差点で、見通しが悪い場合の通行方法はどれか。', '["警音器を鳴らしてそのまま通過する","徐行し、左右の安全をしっかり確認してから通過する","一時停止の標識がないので、速度を落とさず通過する","対向車が来ないことを確認して加速する"]', 1, 1, '見通しの悪い交差点は徐行義務があります。一時停止の有無に関わらず、安全確認を怠ってはいけません。', 'hazard_residential_ball');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_hazard', '右折時、対向車線からバイクが直進してきている。どう判断すべきか。', '["バイクは車より小さいので、先に右折しても問題ない","バイクとの距離を遠く感じても、バイクが通過するまで待つ","バイクの速度が遅いと判断し、急いで右折する","バイクに道を譲ってもらうために合図を送る"]', 1, 2, 'バイクは車より遠く感じやすく、速度を速く誤認しやすいです。右直事故を防ぐため、バイクの通過を待つのが安全です。', 'hazard_intersection_bike');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_hazard', '雨の夜間、歩行者が黒っぽい服を着て道路を歩いている。見落としを防ぐには。', '["ハイビームを常時使用する","速度を十分に落とし、歩行者の有無を注意深く確認する","歩行者を見つけたら警音器を鳴らして退避させる","街灯の多い道だけを選んで走行する"]', 1, 2, '雨の夜間は視界が極めて悪く、歩行者の発見が遅れます。速度を落とすことが、発見後の対応時間を確保する唯一の方法です。', 'hazard_night_rain');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_hazard', '高速道路の走行中、急な豪雨で視界が悪化した。どうすべきか。', '["速度を上げて早く目的地に着く","路肩に停車して雨が止むのを待つ","速度を落とし、車間距離を十分にとって走行する","ハザードランプを点灯させて走行し続ける"]', 2, 1, '高速道路での停車は追突の危険があるため原則禁止です。速度を落とし、車間距離を確保して安全に走行を続けます。', 'hazard_highway_merge');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_hazard', '通学バスの横を通過する際、子供がバスの陰から飛び出してきた。どうすべきか。', '["ハンドルを大きく切って回避する","急ブレーキをかけて停止する","そのままの速度で通過する","警音器を鳴らして子供を驚かせる"]', 1, 2, '飛び出しに対しては急ブレーキが最も有効な回避手段です。ただし、後続車への配慮も必要ですが、人命優先です。', 'hazard_school_bus');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_hazard', '自転車を追い越す際、自転車が右側に膨らむ可能性がある。どう予測すべきか。', '["自転車はまっすぐ走るものと信じて追い越す","自転車が障害物を避けるために右に寄る可能性を想定し、十分な間隔を空ける","自転車の横をすり抜けるように素早く加速する","自転車が右に寄ったら警音器を鳴らして警告する"]', 1, 2, '自転車は路面の凹凸や障害物を避けるために急にふらつくことがあります。常に予測して余裕を持つことが重要です。', 'hazard_bicycle_overtake');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_hazard', '住宅街で子供が遊んでいるのを見かけた。どう走行すべきか。', '["子供は車に気づいているはずなので、そのまま通過する","徐行し、子供が飛び出してきても停止できる準備をして通過する","子供に注意するために警音器を鳴らす","子供が道路から離れるまで停車して待つ"]', 1, 1, '子供の行動は予測不能です。徐行し、いつでも停止できる態勢をとることが事故防止の基本です。', 'hazard_residential_ball');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_hazard', '交差点で右折待ちをしている際、対向車が来ている。どう判断するか。', '["対向車が遠ければ、自分の判断で右折してよい","対向車の速度や距離を慎重に見極め、安全に右折できると確信できるまで待つ","対向車が減速したので、合図なしで右折する","対向車が来る前に急いで右折する"]', 1, 2, '右折時の判断ミスは重大事故に直結します。確信が持てない場合は無理に右折せず、対向車の通過を待つのが鉄則です。', 'hazard_intersection_bike');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_hazard', '生活道路（中央線なし）を走行中、前方にボールが転がってきた。このとき、最も適切な運転行動はどれか。', '["ボールを避けてそのままの速度で通過する","直ちに停止できるよう速度を落とし、子供の飛び出しに備える","対向車がいないことを確認し、右側に寄って回避する","クラクションを鳴らして周囲に注意を促し、加速して通過する"]', 1, 1, '生活道路は最高速度30km/h制限です。ボールの先には必ず子供がいると予測し、急停止可能な速度まで減速するのが鉄則です。', 'hazard_residential_ball');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_hazard', '夕暮れ時、信号のない交差点で自転車が一時停止せずに進入してきた。どう対応すべきか。', '["自転車が優先なので、自分が停止して道を譲る","自分の方が優先道路を走行しているため、そのままの速度で進行する","自転車に注意を促すため、パッシングをしてから通過する","自転車が止まることを期待して、速度を維持して通過する"]', 0, 2, '夕暮れ時は視認性が低下します。相手の違反を期待せず、事故を回避するために譲り合いの精神を持つことが安全運転の基本です。', 'hazard_intersection_bike');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_hazard', '雨の夜、見通しの悪いカーブで対向車が中央線をはみ出してきた。最も適切な回避行動はどれか。', '["対向車に気づかせるため、ハイビームに切り替える","ブレーキを強く踏み、その場で停止する","左側に寄せて減速し、衝突を回避するスペースを確保する","対向車を避けるため、右側にハンドルを切る"]', 2, 2, '雨の夜は路面が滑りやすく視界も悪いです。急ブレーキはスリップの原因となるため、左側に寄せて減速し、衝突を避けるのが正解です。', 'hazard_night_rain');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_hazard', '高速道路の合流地点で、本線上の車がこちらに気づいていない可能性がある。どうすべきか。', '["加速して本線の車の前に割り込む","速度を落として本線の車の後ろに入るように調整する","クラクションを鳴らして自分の存在を知らせる","本線の車の速度が上がるのを待ってから合流する"]', 1, 2, '合流では無理な割り込みは厳禁です。本線の車の流れを妨げないよう、速度調整を行い、安全な車間距離を確保して合流します。', 'hazard_highway_merge');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_hazard', 'スクールバスが停車し、子供が乗り降りしている。追い越す際の注意点はどれか。', '["対向車がいなければ、そのままの速度で追い越す","一時停止し、子供の動きを確認してから徐行して通過する","クラクションを短く鳴らして注意を促し、追い越す","バスの死角に入らないよう、加速して素早く追い越す"]', 1, 1, '停車中のスクールバス周辺は子供の飛び出しが非常に多いです。法令上も安全を確認するまで徐行または停止する義務があります。', 'hazard_school_bus');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_hazard', '自転車を追い越す際、適切な側方間隔はどれか。', '["自転車が転倒しない程度の距離があればよい","安全な側方間隔を空けるか、徐行して追い越す","追い越し禁止場所でなければ、速度を上げて素早く追い越す","自転車のすぐ横を通り、追い越し時間を短縮する"]', 1, 2, '2026年4月施行の改正法により、自転車追い越し時の安全確保が厳格化されました。十分な間隔か徐行が必須です。', 'hazard_bicycle_overtake');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_hazard', '駐車場から道路に出る際、歩道に自転車が走ってきた。どうすべきか。', '["歩道の手前で一時停止し、自転車の通過を待つ","自転車が避けてくれるだろうと考え、ゆっくり進入する","歩道に少し車体を出して、自転車に停止を促す","自転車の速度が遅ければ、そのまま加速して合流する"]', 0, 1, '歩道横断時は歩道の手前で一時停止し、歩行者や自転車の通行を妨げないことが道路交通法上の義務です。', 'hazard_residential_ball');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_hazard', '下り坂のカーブで、対向車がスピードを出しすぎているように見える。どう対応するか。', '["自分も速度を上げてカーブを曲がりきる","ブレーキをかけながら、できるだけ左側に寄って進行する","対向車に注意を促すため、ヘッドライトを点滅させる","カーブの頂点で停止し、対向車が通過するのを待つ"]', 1, 2, '下り坂は制動距離が伸びます。対向車のはみ出しを予測し、左側に寄せて衝突の危険を最小限に抑えるのが賢明です。', 'hazard_night_rain');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_hazard', '踏切の手前で渋滞している。どうすべきか。', '["踏切内に車が入らないよう、踏切の手前で停止して待つ","前の車が動いたら、踏切内に停止してもよいので進む","踏切内で停止しないよう、加速して通過する","踏切の警報機が鳴っていないことを確認し、進入する"]', 0, 1, '踏切内での立ち往生は重大事故に直結します。渋滞時は踏切の手前で待機し、確実に通過できるスペースが空くまで進入してはなりません。', 'hazard_intersection_bike');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_hazard', '夕暮れ時、ライトを点灯するタイミングとして最も適切なのはどれか。', '["周囲が完全に暗くなってから","街灯が点灯し始めてから","視界が悪くなる前の早い時間帯から点灯する","対向車がライトを点灯し始めてから"]', 2, 1, '夕暮れ時は「薄暮時」と呼ばれ、事故が多発します。自分の視界確保だけでなく、他車への存在アピールのため早めの点灯が鉄則です。', 'hazard_night_rain');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_hazard', '死角から子供が飛び出してきた。ブレーキを踏むまでの「空走距離」について正しい説明はどれか。', '["運転者の反応速度によって変わるが、速度が速いほど長くなる","路面の状態によってのみ変化する","ブレーキの性能によってのみ変化する","速度に関わらず一定である"]', 0, 2, '空走距離は「危険を感じてからブレーキを踏むまでの距離」です。速度が速いほど、また反応が遅れるほど長くなります。', 'hazard_residential_ball');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_hazard', '交差点で右折する際、対向直進車が来ている。どう判断すべきか。', '["自分の車の方が先に交差点に入ったので、優先して右折する","対向車の速度が遅ければ、無理をしてでも右折する","対向車が通過するのを待ってから右折する","対向車にパッシングをして、道を譲るよう合図する"]', 2, 1, '右折車は直進車を妨げてはなりません。対向車の距離や速度を誤認しやすいため、確実に安全を確認してから右折します。', 'hazard_intersection_bike');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_hazard', '雨の日の運転で、ハイドロプレーニング現象を防ぐためにすべきことはどれか。', '["速度を落とし、タイヤの空気圧を適切に保つ","急ブレーキを避けるため、速度を上げて通過する","タイヤを太いものに交換する","車間距離を詰め、前の車の轍（わだち）を走る"]', 0, 2, 'ハイドロプレーニングはタイヤと路面の間に水膜ができる現象です。速度を落とすことが最も有効な対策です。', 'hazard_night_rain');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_hazard', '高速道路の渋滞末尾に近づいた際、後続車への合図として適切なものはどれか。', '["ハザードランプを点灯させ、後続車に減速を伝える","急ブレーキを踏んで、渋滞していることを知らせる","クラクションを鳴らしながら停車する","そのままの速度で走行し、直前で停止する"]', 0, 1, '高速道路での追突事故を防ぐため、渋滞末尾ではハザードランプを点灯し、後続車にいち早く減速を知らせるのがマナーであり安全策です。', 'hazard_highway_merge');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_hazard', '自転車が前方を走行中、左折しようとしている。どうすべきか。', '["自転車を追い抜いてから左折する","自転車の左側をすり抜けて左折する","自転車の動きを予測し、巻き込み防止のため一時停止や減速を行う","クラクションを鳴らして自転車を路肩に寄せる"]', 2, 2, '左折時の巻き込み事故は非常に多いです。自転車の直前で左折せず、自転車の動きを十分に確認してから行動します。', 'hazard_bicycle_overtake');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_hazard', '駐車場から出る際、死角から歩行者が現れる可能性がある。どうすべきか。', '["徐行しながら、いつでも停止できるようにして進行する","左右の安全確認をせず、素早く道路に出る","クラクションを鳴らしながら、勢いよく道路に出る","歩行者がいないことを確認し、加速して出る"]', 0, 1, '駐車場出入口は死角が多く、歩行者や自転車が飛び出してくる可能性が高い場所です。徐行と安全確認が必須です。', 'hazard_residential_ball');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_hazard', '踏切を通過する際、変速操作（ギアチェンジ）を行うべきか。', '["踏切内では変速操作をしてはならない","踏切に入る直前に、高速ギアに切り替える","踏切内で速度を調整するため、適宜変速する","踏切の幅が広ければ、変速しても問題ない"]', 0, 2, '踏切内でのエンストを防ぐため、踏切に入る前に低速ギアに入れ、踏切内では変速操作をせず一気に通過するのが鉄則です。', 'hazard_intersection_bike');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_hazard', '夕暮れ時、無灯火の自転車を追い越す際の注意点はどれか。', '["自転車が気づいていない可能性があるため、十分な側方間隔を空けて徐行する","ライトを点灯させるよう、横を通りながら声をかける","追い越し禁止場所ではないので、速度を上げて追い越す","自転車のすぐ後ろを走り、ライトの代わりになる"]', 0, 2, '無灯火の自転車は視認性が極めて低いです。相手がこちらに気づいていない前提で、距離を空けて慎重に追い越します。', 'hazard_bicycle_overtake');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_hazard', '中央線のある一般道路の法定最高速度は時速何キロか。', '["30km/h","40km/h","50km/h","60km/h"]', 3, 1, '2026年11月時点の法規では、中央線や車両通行帯のある一般道路は原則60km/h、ない生活道路は30km/hです。', 'hazard_highway_merge');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_hazard', '子供が乗っているスクールバスを追い越す際、子供が飛び出してくるかもしれない。この予測は正しいか。', '["正しい。子供の予期せぬ行動を予測して運転すべきである","間違い。バスが停車していれば飛び出しは起こらない","間違い。子供は交通ルールを守るため、飛び出しはしない","正しいが、バスの運転手が注意しているため心配ない"]', 0, 1, '危険予測において「かもしれない運転」は基本です。子供の行動は予測不能であると考えるのが安全運転の鉄則です。', 'hazard_school_bus');
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '運転適性検査における「性格検査」の回答において、最も適切な姿勢はどれか。', '["自分を良く見せようとせず、直感的に正直に回答する","理想的な運転者像を想定し、それに合わせて回答する","迷った場合は、時間がかかっても慎重に考え直す","検査の意図を読み取り、好評価を得られるように調整する"]', 0, 1, '性格検査は自己分析と安全運転への気づきが目的です。偽りの回答をすると正確な判定が出ず、自身の危険な傾向を把握できません。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', 'OD式安全性テスト等の適性検査の主な目的として、最も適切なものはどれか。', '["運転技術の優劣を判定し、免許の合否を決めるため","自身の性格や運転行動の傾向を把握し、事故防止に役立てるため","知能指数を測定し、交通ルールの理解度を評価するため","身体的な障害の有無を厳格にチェックするため"]', 1, 1, '適性検査は技術試験ではなく、個人の性格や行動特性を客観的に把握し、安全運転のための自己管理能力を高めることを目的としています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '運転中の「安全態度」として、最も望ましい考え方はどれか。', '["自分は運転が上手いので、多少の無理は問題ない","交通ルールを守ることは、他者への配慮であると考える","急いでいる時は、ルールよりも目的地への到着を優先する","他車が譲ってくれることを前提に運転する"]', 1, 1, '安全運転は単なるルールの遵守だけでなく、他者への思いやりと譲り合いの精神が不可欠です。自分本位な考えは事故の元となります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '運転適性検査の結果で「衝動性が高い」と判定された場合、運転時に特に注意すべきことはどれか。', '["走行速度を上げ、素早く目的地に到着する","イライラした時は深呼吸をし、気持ちを落ち着かせてから運転する","他車の動きを無視して、自分のペースで走行する","交通量の多い道路を避け、常に裏道を利用する"]', 1, 2, '衝動性が高い人は、感情に任せた運転をしがちです。自覚を持つことで、冷静さを保つためのセルフコントロールが可能になります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '運転適性検査の回答で「一貫性がない」と判定される主な原因は何か。', '["回答のスピードが速すぎたため","自分を良く見せようとして、回答に矛盾が生じているため","質問内容を理解せずに適当に回答したため","性格が多重人格であるため"]', 1, 2, '正直に回答せず、理想の自分を演じようとすると、似たような質問に対して矛盾した回答をしてしまい、信頼性が低いと判定されます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '運転適性検査の結果をどのように活用すべきか。', '["結果が悪ければ免許は取得できないので、再検査を受ける","自分の運転の弱点を知り、今後の安全運転の参考にし、意識改善に努める","結果はあくまで統計的なものであり、全く気にする必要はない","結果を家族や友人に公開し、アドバイスをもらう"]', 1, 1, '検査結果は合否を決めるものではなく、自分の運転特性を客観視し、事故を未然に防ぐための「気づき」のツールとして活用します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '運転適性検査における「動作の正確さ」が低いと判定された場合、どのような運転に注意すべきか。', '["ハンドル操作やブレーキ操作が雑になりやすいため、丁寧な操作を心がける","速度を出しすぎる傾向があるため、常に低速で走行する","判断が遅れる傾向があるため、常に前の車にぴったりついて走る","視力が低下している可能性があるため、眼鏡を新調する"]', 0, 2, '動作の正確さが低いと、急ハンドルや急ブレーキなど操作が荒くなりがちです。意識的に丁寧な操作を心がけることが事故防止に繋がります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '安全運転において「予測」が重要である理由はどれか。', '["予測を立てれば、交通ルールを無視しても事故にならないから","危険を事前に察知することで、回避行動をとる余裕が生まれるから","予測を立てることで、目的地までの時間を短縮できるから","予測は警察官の指示に従うために必要だから"]', 1, 1, '「かもしれない運転」を実践することで、急な飛び出しや他車のミスにも対応できる心の準備と時間的余裕が生まれます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '運転適性検査で「自己顕示性が強い」と判定された場合、どのようなリスクがあるか。', '["慎重になりすぎて、周囲の流れを乱す","スピードの出しすぎや無理な追い越しなど、目立つ運転をしがちになる","判断が遅れ、交差点での事故を起こしやすい","標識を見落とす可能性が高くなる"]', 1, 2, '自己顕示性が強いと、周囲に自分を誇示したいという心理が働き、危険な追い越しや速度超過などのリスク行動に繋がりやすくなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '運転適性検査の「判断力」の項目で、特に重視されることは何か。', '["複雑な交通状況下で、素早く的確な判断ができるか","標識の名称を全て暗記しているか","車の構造や整備に関する知識があるか","長時間の運転に耐えられる体力があるか"]', 0, 2, '運転は刻々と変化する状況の連続です。瞬時に状況を分析し、適切な対応を選択する能力が安全運転の根幹となります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '運転適性検査の性格検査において、質問文を読み飛ばして回答することの弊害は何か。', '["検査時間が短縮されるので、効率が良い","自分の本当の傾向が反映されず、安全運転のための自己分析ができない","検査員に怒られる可能性がある","免許証の交付が遅れる"]', 1, 1, '適当な回答は、自身の性格や運転傾向を正しく把握する機会を失わせます。自分自身の安全を守るために、真摯に取り組むべきです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '安全運転に必要な「協調性」とは、どのような態度を指すか。', '["自分の進路を優先し、他車を排除する態度","交通ルールを守り、他車の動きを尊重して譲り合う態度","前の車に続いて、同じ速度で走行する態度","信号が青になったら、すぐに発進する態度"]', 1, 1, '協調性は、交通社会の一員として他者と円滑に共存するための重要な要素です。譲り合いの精神が事故を減らします。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '運転適性検査の結果で「情緒不安定」と判定された場合、運転前にすべきことは何か。', '["音楽を大音量で聴き、気分を盛り上げる","自分の感情の状態を客観的に認識し、落ち着いてから運転する","目的地まで急ぐために、少し無理をしてでも出発する","誰かに電話をかけて、気分を紛らわせる"]', 1, 2, '感情の起伏は運転操作に悪影響を与えます。イライラや不安がある時は、運転を控えるか、落ち着くまで休憩することが重要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '運転適性検査の「動作の速さ」が過剰に高い場合、どのような危険が考えられるか。', '["反応が遅すぎて事故になる","操作が早すぎて、確認不足や急な操作になりやすい","眠気を感じやすくなる","標識の意味を理解できなくなる"]', 1, 2, '動作が速すぎると、周囲の確認が疎かになったり、操作が雑になりがちです。正確さを伴わない速さは危険を招きます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '運転適性検査の目的として、誤っているものはどれか。', '["運転者の性格や行動特性を把握する","安全運転のためのアドバイスを提供する","運転の技術を数値化し、ランク付けする","事故の傾向を分析し、防止策を考える"]', 2, 1, '適性検査は運転技術の優劣をランク付けするものではありません。あくまで個人の特性を理解し、安全運転に役立てるためのものです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '運転適性検査において、自分の性格を「過小評価」して回答するリスクは何か。', '["自分の危険な傾向に気づけず、事故のリスクが高まる","検査結果が良すぎて、逆に不安になる","免許の取得が取り消される","教習料金が割増になる"]', 0, 2, '自分を過小評価（あるいは過大評価）して回答すると、正しい自己分析ができず、本来注意すべき自分の弱点が放置されてしまいます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '安全運転において「責任感」を持つとは、どういうことか。', '["事故を起こした時に、金銭的な賠償をすることだけを考える","車の運転は他人の命を預かる行為であると自覚し、常に慎重に行動する","交通ルールは守るが、他車の違反には厳しく対処する","自分の運転に自信を持ち、他人の意見を聞かない"]', 1, 1, '運転者は、自分だけでなく同乗者や歩行者、他車の命を守る責任があります。この自覚が安全運転の原点です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '運転適性検査で「攻撃的」と判定された場合、運転中にどのような行動に注意すべきか。', '["他車に煽られた際、すぐに道を譲る","前の車が遅いとイライラし、無理な追い越しをしようとする","常に制限速度以下で走行する","交差点では必ず一時停止する"]', 1, 2, '攻撃的な傾向がある人は、他車の動きに対してイライラしやすく、あおり運転や無理な追い越しといった危険行動に走りやすい傾向があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '運転適性検査の「集中力」の項目で、高いスコアを維持するために必要なことは何か。', '["運転中に長時間音楽を聴き続ける","十分な睡眠をとり、体調を整えて運転に臨む","運転中にスマートフォンで情報を確認する","常に周囲の車と競いながら走る"]', 1, 1, '集中力は体調に大きく左右されます。睡眠不足や疲労は集中力を著しく低下させるため、体調管理は運転者としての義務です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '運転適性検査の回答で「迷った」場合、どうするのが最も良いか。', '["直感的に、今の自分に最も近いと感じるものを選ぶ","時間をかけて、正解と思われる選択肢を探す","回答を保留にして、次の問題に進む","適当に選んで、早く終わらせる"]', 0, 1, '性格検査に正解はありません。迷った時は、深く考えすぎず、直感的に自分に当てはまるものを選ぶのが最も正確な結果に繋がります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '運転適性検査の結果を「受け入れられない」と感じた場合、どうすべきか。', '["検査結果を無視し、自分の運転スタイルを貫く","結果を否定せず、なぜそのような判定が出たのかを冷静に振り返る","教習所に抗議し、再検査を要求する","自分の性格が悪いのだと落ち込み、運転を諦める"]', 1, 2, '自分では気づいていない癖や傾向を指摘されるのが適性検査です。結果を否定せず、自己改善のヒントとして受け入れる姿勢が大切です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '運転適性検査の「判断の正確さ」が低いと判定された場合、どのような運転が推奨されるか。', '["余裕を持った運転を心がけ、危険予測の時間を十分に確保する","スピードを上げて、判断の回数を減らす","他車の動きを予測せず、自分の直感を信じる","常に前の車にぴったりついて走る"]', 0, 2, '判断に時間がかかる、あるいはミスが多い場合は、速度を控えめにし、車間距離を広く取ることで、判断のための時間的余裕を確保しましょう。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '運転適性検査の「性格検査」で、同じような質問が繰り返される理由は何か。', '["回答者が真剣に答えているかを確認するため","回答の一貫性を確認し、信頼性を高めるため","検査時間を長くして、集中力を測定するため","質問の作成ミスを防ぐため"]', 1, 2, '似た質問を繰り返すことで、回答に矛盾がないかを確認し、回答の信頼性（一貫性）を判定しています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '安全運転の態度として「謙虚さ」が重要な理由はどれか。', '["謙虚であれば、事故を起こしても許されるから","自分の未熟さを認め、常に学び続ける姿勢が事故を防ぐから","謙虚な運転者は、警察に捕まりにくいから","謙虚さは、車の燃費を向上させるから"]', 1, 1, '「自分は運転が上手い」という過信は慢心を生みます。常に謙虚な姿勢で運転することで、慢心を防ぎ、安全意識を高く保てます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '運転適性検査の「性格検査」で、最も避けるべき回答態度はどれか。', '["正直に回答する","自分を良く見せようとして、不自然な回答を繰り返す","直感的に回答する","質問文をよく読んで回答する"]', 1, 1, '自分を良く見せようとする回答は、検査の信頼性を損なうだけでなく、自身の危険な特性を隠蔽することになり、極めて危険です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '運転適性検査における「注意配分」の能力が高い運転者とは、どのような状態を指すか。', '["一つの対象に集中し、周囲の状況を遮断できる能力","複数の情報を同時に処理し、状況に応じて注意を切り替える能力","反応速度を極限まで高め、反射的にブレーキを踏める能力","長時間の運転でも疲労を感じず、集中力を維持できる能力"]', 1, 1, '注意配分とは、複数の交通状況を同時に把握し、優先順位をつけて処理する能力です。一つに固執するのは「注意の狭窄」と呼ばれ危険です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '図形抹消検査において、制限時間内に正確に多くの図形を処理する目的は何か。', '["視力の良さを測定するため","注意の持続力と正確性を測定するため","運転技術の熟練度を測定するため","反射神経の速さを測定するため"]', 1, 1, '図形抹消検査は、単純作業を繰り返す際の集中力、注意の持続力、および正確な判断力を測定するために行われます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '衝動性チェックの結果で「衝動性が高い」と判定された場合、運転時に最も注意すべきことは何か。', '["車間距離を極端に詰めること","急な進路変更や追い越しを控えること","制限速度を厳守しすぎないこと","夜間の運転を避けること"]', 1, 2, '衝動性が高い人は、カッとなりやすく急な操作をしがちです。安全運転のためには、意識的に余裕を持った操作を心がける必要があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '2026年9月施行の改正法に基づき、中央線や車両通行帯のない生活道路での法定最高速度は時速何キロか。', '["時速60km","時速50km","時速40km","時速30km"]', 3, 1, '2026年9月より、中央線や車両通行帯のない一般道路の法定最高速度は時速30kmに引き下げられました。生活道路の安全確保が目的です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '反応速度検査において、光や音に対して反応が遅れる原因として不適切なものはどれか。', '["睡眠不足による疲労","運転に対する過度な緊張","適切な車間距離の保持","飲酒や薬物の影響"]', 2, 1, '適切な車間距離の保持は安全運転の基本であり、反応速度を遅らせる原因にはなりません。他の選択肢はすべて反応を鈍らせる要因です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '自転車の追い越しに関する2026年4月施行のルールとして正しいものはどれか。', '["自転車の右側を時速60kmで追い越してよい","十分な側方間隔または安全な速度で進行しなければならない","自転車は常に左側通行のため、追い越しは禁止されている","自転車のベルが鳴った場合のみ、追い越しを中断する"]', 1, 2, '改正法では、自転車を追い越す際は十分な側方間隔を空けるか、安全な速度で走行することが義務付けられています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '運転適性検査の結果が「運転に向かない」と出た場合、どうすべきか。', '["運転免許の取得を諦める必要がある","自分の性格や傾向を理解し、安全運転に活かす","検査結果を無視して運転技術を磨く","検査結果を他人に隠して運転する"]', 1, 1, '適性検査は免許の可否を決めるものではなく、自分の運転の癖を知り、事故を防ぐための自己管理ツールとして活用すべきです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', 'マイナ免許証の運用に関して正しい記述はどれか。', '["マイナ免許証のみ所持が義務付けられている","従来免許証のみ、マイナ免許証のみ、両方持ちから選択できる","マイナ免許証があれば、従来免許証は即時失効する","マイナ免許証はスマートフォンでのみ表示可能である"]', 1, 2, '2025年3月より、従来型とマイナ免許証の選択制が導入されています。個人のライフスタイルに合わせて選択可能です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '普通免許等の受験資格（仮免・本試験）について、2026年4月施行のルールはどれか。', '["18歳以上でなければ受験できない","17歳6か月以上であれば受験可能である","16歳以上であれば受験可能である","年齢に関係なく教習を修了すれば受験可能である"]', 1, 2, '2026年4月より、受験資格は17歳6か月以上に引き下げられました。ただし、免許証の交付は18歳に達してからとなります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '注意配分が苦手な人が、運転中に心がけるべき最も効果的な対策は何か。', '["音楽を大音量で流してリラックスする","視線を一点に固定して走行する","こまめに休憩を取り、余裕を持った計画を立てる","他の車の動きを無視して自分のペースを守る"]', 2, 2, '注意配分が苦手な人は疲労により判断力が低下しやすいため、計画的な休憩と余裕を持った運転が事故防止に繋がります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '自転車の交通違反に対する青切符制度（16歳以上対象）の目的は何か。', '["自転車の販売価格を抑制するため","自転車利用者の交通ルール遵守意識を高めるため","自転車の走行速度を制限するため","自転車専用道路を増やすため"]', 1, 2, '2026年4月施行の青切符制度は、自転車の悪質な違反を抑止し、交通秩序を維持するために導入されました。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '運転適性検査における「衝動性」が高い人の特徴として、最も危険な運転行動はどれか。', '["信号待ちでエンジンを切る","前の車が遅いとすぐにイライラして追い越そうとする","制限速度を厳守して走行する","車線変更時に必ず合図を出す"]', 1, 1, '衝動性が高い人は、自分の思い通りにならない状況で感情を制御できず、強引な運転になりがちです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '運転中に「注意配分」を適切に行うために必要なことは何か。', '["常に遠くの景色を眺める","ルームミラーやサイドミラーを定期的に確認する","スピードメーターを常に凝視する","カーナビの操作を優先する"]', 1, 1, '周囲の状況を把握するためには、前方だけでなく、ミラー等を用いて死角や後方の情報を適宜取り入れる必要があります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '反応速度が遅いと自覚している人が、安全のためにすべきことは何か。', '["反応を補うために、より速い速度で走行する","車間距離を通常より長めにとる","反応を速くするために薬を服用する","夜間の運転を控えるだけで十分である"]', 1, 2, '反応が遅い分、物理的な距離（車間距離）を確保することで、危険を察知してから停止するまでの時間を稼ぐことができます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '図形抹消検査でミスが多い場合、実際の運転でどのようなリスクがあるか。', '["標識の見落としや、確認不足による事故","車の操作方法を忘れる","エンジンの故障に気づかない","ガソリンの残量を忘れる"]', 0, 2, '図形抹消検査でのミスは、注意力の欠如や見落としの傾向を示唆しており、運転中の標識や歩行者の見落としに直結します。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '生活道路（中央線なし）で時速30km制限が設けられた主な理由は何か。', '["車の燃費を向上させるため","歩行者や自転車との接触時の被害を軽減するため","道路の舗装を長持ちさせるため","渋滞を緩和するため"]', 1, 1, '生活道路は歩行者や自転車が多く、万が一の衝突時に死亡事故を防ぐために速度抑制が重要視されています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '運転適性検査の「性格診断」において、協調性が低いと判定された場合の対策は。', '["他の車を気にせず自分の運転を貫く","譲り合いの精神を持ち、無理な割り込みをしない","運転を控える","他の車に道を譲らせるようにする"]', 1, 2, '協調性が低いと、自分勝手な運転になりがちです。譲り合いの精神を持つことで、周囲とのトラブルを回避できます。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '自転車の追い越しにおいて「安全な速度」とはどのような状態を指すか。', '["制限速度ギリギリの速度","自転車が急にふらついても即座に停止できる速度","前の車と同じ速度","時速20km以上の速度"]', 1, 2, '自転車はふらつきや急な進路変更の可能性があるため、いつでも停止できる速度で追い越すことが安全確保の要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '運転適性検査の結果をどのように活用するのが最も適切か。', '["自分の運転の弱点を理解し、意識的に注意を払う","結果が良かったら、どんな運転をしても良いと考える","結果が悪い項目は無視する","他人の結果と比較して優越感に浸る"]', 0, 1, '適性検査は自分の傾向を知るためのものです。弱点を自覚し、それをカバーする運転を心がけることが事故防止に繋がります。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '注意配分能力を低下させる要因として、最も不適切なものはどれか。', '["運転中のスマートフォン操作","考え事をしながらの運転","適切な車間距離の確保","強い眠気"]', 2, 1, '車間距離の確保は安全運転の基本であり、注意配分を低下させる要因にはなりません。他の選択肢はすべて注意を逸らす要因です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '衝動性を抑えるための運転テクニックとして正しいものはどれか。', '["前の車を煽ってプレッシャーをかける","急いでいる時は制限速度を無視する","深呼吸をして、心に余裕を持って運転する","イライラしたら加速して早く目的地に着く"]', 2, 1, '感情のコントロールは安全運転の要です。イライラを感じたら深呼吸をして冷静さを取り戻すことが重要です。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '17歳6か月で仮免許を取得した者が、路上練習をする際の注意点はどれか。', '["18歳になるまでは練習してはならない","指導員や免許保有者の同乗が必須である","深夜であれば一人で練習してもよい","高速道路で練習しなければならない"]', 1, 2, '仮免許練習中は、免許保有者や指導員の同乗が義務付けられています。年齢に関わらずルールは同じです。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '図形抹消検査で「正確さ」が重視される理由は何か。', '["運転において、一つ一つの確認が命に関わるから","早く終わらせる能力が運転に必要だから","図形を正確に描く能力が必要だから","検査官が採点しやすくするため"]', 0, 2, '運転は正確な判断の連続です。検査での正確さは、実際の運転における確認作業の質を反映しています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', 'マイナ免許証を選択するメリットとして正しいものはどれか。', '["運転免許証の更新手続きがオンラインで完結しやすくなる","運転技術が向上する","制限速度が緩和される","免許証を携帯しなくてよくなる"]', 0, 2, 'マイナ免許証はデジタル化による利便性向上が目的です。更新手続きの簡素化などが期待されています。', NULL);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty, explanation, image_key) VALUES ('all', 'driving_aptitude', '運転適性検査の目的として、最も適切なものはどれか。', '["運転の才能があるかを判定するため","個人の運転傾向を把握し、事故防止に役立てるため","免許証の交付を拒否するため","教習所の指導員の評価をするため"]', 1, 1, '適性検査は、自身の運転における癖や傾向を客観的に知り、安全運転に活かすための教育的なツールです。', NULL);
